static void run_timers(JSContext *ctx)
{
    int64_t min_delay, delay, cur_time;
    BOOL has_timer;
    int i;
    JSTimer *th;
    struct timespec ts;
    for(;;) {
        min_delay = 1000;
        cur_time = get_time_ms();
        has_timer = FALSE;
        for(i = 0; i < MAX_TIMERS; i++) {
            th = &js_timer_list[i];
            if (th->allocated) {
                has_timer = TRUE;
                delay = th->timeout - cur_time;
                if (delay <= 0) {
                    JSValue ret;
                    if (JS_StackCheck(ctx, 2))
                        goto fail;
                    JS_PushArg(ctx, th->func.val); 
                    JS_PushArg(ctx, JS_NULL); 
                    JS_DeleteGCRef(ctx, &th->func);
                    th->allocated = FALSE;
                    ret = JS_Call(ctx, 0);
                    if (JS_IsException(ret)) {
                    fail:
                        dump_error(ctx);
                        exit(1);
                    }
                    min_delay = 0;
                    break;
                } else if (delay < min_delay) {
                    min_delay = delay;
                }
            }
        }
        if (!has_timer)
            break;
        if (min_delay > 0) {
            ts.tv_sec = min_delay / 1000;
            ts.tv_nsec = (min_delay % 1000) * 1000000;
            nanosleep(&ts, NULL);
        }
    }
}

void scene_update(void* data) {
    SC_PROFILE_START(scene);
    struct scene* scene = (struct scene*)data;
    struct Vector3 player_center = scene->player.cutscene_actor.transform.position;
    player_center.y += scene->player.cutscene_actor.collider.type->center.y;
    SC_PROFILE_START(scene);
    for (int i = 0; i < scene->loading_zone_count; i += 1) {
        struct loading_zone* zone = &scene->loading_zones[i];
        vector3_t rotated_center;
        vector3RotateWith2Inv(&player_center, &zone->rotation, &rotated_center);
        if (box3DContainsPoint(&zone->bounding_box, &rotated_center)) {
            cutscene_builder_t cutscene;
            cutscene_builder_init(&cutscene);
