            cutscene_builder_pause(&cutscene, false, false, UPDATE_LAYER_WORLD);
            cutscene_runner_run(cutscene_builder_finish(&cutscene), 0, cutscene_runner_free_on_finish(), NULL, 0);
            scene->loading_zone_count = 0;
        }
