void carve(int x, int y) {
    maze[y * WIDTH + x] = ' ';
    int dirs[] = {0, 1, 2, 3};
    for (int i = 3; i > 0; i--) {
        int j = (unsigned)mulberry32() % (i + 1);
        int tmp = dirs[i];
        dirs[i] = dirs[j];
        dirs[j] = tmp;
    }
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[dirs[i]] * 2;
        int ny = y + dy[dirs[i]] * 2;
        if (in_bounds(nx, ny) && maze[ny * WIDTH + nx] != '#') {
            maze[(y + dy[dirs[i]]) * WIDTH + (x + dx[dirs[i]])] = ' ';
            carve(nx, ny);
        }
    }
}

