t claw_ota_do_update(const char *url, claw_ota_progress_cb progress)
{
    if (!url || url[0] == '\0') {
        return CLAW_ERROR;
    }
    char *buf = claw_malloc(OTA_BUF_SIZE);
    if (!buf) {
        CLAW_LOGE(TAG, "no memory for OTA buffer");
        return CLAW_ERROR;
    }
    esp_http_client_config_t http_cfg = {
        .url = url,
        .timeout_ms = 30000,
        .crt_bundle_attach = esp_crt_bundle_attach,
        .buffer_size = 2048,
        .keep_alive_enable = true,
    };
    esp_http_client_handle_t client = esp_http_client_init(&http_cfg);
    if (!client) {
        claw_free(buf);
        return CLAW_ERROR;
    }
    esp_err_t err = esp_http_client_open(client, 0);
    if (err != ESP_OK) {
        CLAW_LOGE(TAG, "HTTP open failed: %s", esp_err_to_name(err));
        esp_http_client_cleanup(client);
        claw_free(buf);
        return CLAW_ERROR;
    }
    int content_length = esp_http_client_fetch_headers(client);
    uint32_t total_size = (content_length > 0) ? (uint32_t)content_length : 0;
    CLAW_LOGI(TAG, "firmware size: %lu bytes",
              (unsigned long)total_size);
    const esp_partition_t *update_part =
        esp_ota_get_next_update_partition(NULL);
    if (!update_part) {
        CLAW_LOGE(TAG, "no update partition");
        esp_http_client_close(client);
        esp_http_client_cleanup(client);
        claw_free(buf);
        return CLAW_ERROR;
    }
    esp_ota_handle_t ota_handle = 0;
    err = esp_ota_begin(update_part, OTA_WITH_SEQUENTIAL_WRITES,
                        &ota_handle);
    if (err != ESP_OK) {
        CLAW_LOGE(TAG, "esp_ota_begin failed: %s", esp_err_to_name(err));
        esp_http_client_close(client);
        esp_http_client_cleanup(client);
        claw_free(buf);
        return CLAW_ERROR;
    }
    uint32_t received = 0;
    int ret = CLAW_OK;
    while (1) {
        int read_len = esp_http_client_read(client, buf, OTA_BUF_SIZE);
        if (read_len < 0) {
            CLAW_LOGE(TAG, "HTTP read error");
            ret = CLAW_ERROR;
            break;
        }
        if (read_len == 0) {
            if (esp_http_client_is_complete_data_received(client)) {
                break;
            }
            if (total_size > 0 && received < total_size) {
                CLAW_LOGE(TAG, "incomplete download: %lu / %lu",
                          (unsigned long)received,
                          (unsigned long)total_size);
                ret = CLAW_ERROR;
            }
            break;
        }
        err = esp_ota_write(ota_handle, buf, (size_t)read_len);
        if (err != ESP_OK) {
            CLAW_LOGE(TAG, "esp_ota_write failed: %s",
                      esp_err_to_name(err));
            ret = CLAW_ERROR;
            break;
        }
        received += (uint32_t)read_len;
        if (progress) {
            progress(received, total_size);
        }
    }
    esp_http_client_close(client);
    esp_http_client_cleanup(client);
    claw_free(buf);
    if (ret != CLAW_OK) {
        esp_ota_abort(ota_handle);
        return CLAW_ERROR;
    }
    err = esp_ota_end(ota_handle);
    if (err != ESP_OK) {
        CLAW_LOGE(TAG, "esp_ota_end failed: %s", esp_err_to_name(err));
        return CLAW_ERROR;
    }
    err = esp_ota_set_boot_partition(update_part);
    if (err != ESP_OK) {
        CLAW_LOGE(TAG, "set boot partition failed: %s",
                  esp_err_to_name(err));
        return CLAW_ERROR;
    }
    CLAW_LOGI(TAG, "OTA succeeded, new boot partition: %s",
              update_part->label);
    return CLAW_OK;
}

static void shellAddSchemaName(
  sqlite3_context *pCtx,
  int nVal,
  sqlite3_value **apVal
){
  static const char *aPrefix[] = {
     "TABLE",
     "INDEX",
     "UNIQUE INDEX",
     "VIEW",
     "TRIGGER",
     "VIRTUAL TABLE"
  };
  int i = 0;
  const char *zIn = (const char*)sqlite3_value_text(apVal[0]);
  const char *zSchema = (const char*)sqlite3_value_text(apVal[1]);
  const char *zName = (const char*)sqlite3_value_text(apVal[2]);
  sqlite3 *db = sqlite3_context_db_handle(pCtx);
  UNUSED_PARAMETER(nVal);
  if( zIn!=0 && cli_strncmp(zIn, "CREATE ", 7)==0 ){
    for(i=0; i<ArraySize(aPrefix); i++){
      int n = strlen30(aPrefix[i]);
      if( cli_strncmp(zIn+7, aPrefix[i], n)==0 && zIn[n+7]==' ' ){
        char *z = 0;
        char *zFake = 0;
        if( zSchema ){
          char cQuote = quoteChar(zSchema);
          if( cQuote && sqlite3_stricmp(zSchema,"temp")!=0 ){
            z = sqlite3_mprintf("%.*s \"%w\".%s", n+7, zIn, zSchema, zIn+n+8);
          }else{
            z = sqlite3_mprintf("%.*s %s.%s", n+7, zIn, zSchema, zIn+n+8);
          }
        }
        if( zName
         && aPrefix[i][0]=='V'
         && (zFake = shellFakeSchema(db, zSchema, zName))!=0
        ){
          if( z==0 ){
            z = sqlite3_mprintf("%s\n", zIn, zFake);
          }else{
            z = sqlite3_mprintf("%z\n", z, zFake);
          }
          sqlite3_free(zFake);
        }
        if( z ){
          sqlite3_result_text(pCtx, z, -1, sqlite3_free);
          return;
        }
      }
    }
  }
  sqlite3_result_value(pCtx, apVal[0]);
}

