    va_end(ap);
    if (s_cap.buf && s_cap.pos < s_cap.size - 1) {
        char tmp[512];
        va_start(ap, fmt);
        int n = vsnprintf(tmp, sizeof(tmp), fmt, ap);
        va_end(ap);
        if (n <= 0) {
            size_t avail = s_cap.size - 1 - s_cap.pos;
            size_t written = strip_ansi(tmp, (size_t)n,
