static void SerialUpdate(float H[NUMV][NUMX], float R[NUMV], float Z[NUMV],
		  float Y[NUMV], float P[NUMX][NUMX], float X[NUMX],
		  uint16_t SensorsUsed)
{
	float HP[NUMX], HPHR, Error;
	uint8_t i, j, k, m;
	for (m = 0; m < NUMV; m++) {
		if (SensorsUsed & (0x01 << m)) {	
			for (j = 0; j < NUMX; j++) {	
				HP[j] = 0;
				for (k = 0; k < NUMX; k++)
					HP[j] += H[m][k] * P[k][j];
			}
			HPHR = R[m];	
			for (k = 0; k < NUMX; k++)
				HPHR += HP[k] * H[m][k];
			for (k = 0; k < NUMX; k++)
				K[k][m] = HP[k] / HPHR;	
			for (i = 0; i < NUMX; i++) {	
				for (j = i; j < NUMX; j++)
					P[i][j] = P[j][i] =
					    P[i][j] - K[i][m] * HP[j];
			}
			Error = Z[m] - Y[m];
			for (i = 0; i < NUMX; i++)	
				X[i] = X[i] + K[i][m] * Error;
		}
	}
}

