static int read_gsm_triplets(const char *fname)
{
	FILE *f;
	char buf[200], *pos, *pos2;
	struct gsm_triplet *g = NULL;
	int line, ret = 0;
	if (fname == NULL)
		return -1;
	f = fopen(fname, "r");
	if (f == NULL) {
		printf("Could not open GSM triplet data file '%s'\n", fname);
		return -1;
	}
	line = 0;
	while (fgets(buf, sizeof(buf), f)) {
		line++;
		buf[sizeof(buf) - 1] = '\0';
		if (buf[0] == '#')
			continue;
		pos = buf;
		while (*pos != '\0' && *pos != '\n')
			pos++;
		if (*pos == '\n')
			*pos = '\0';
		pos = buf;
		if (*pos == '\0')
			continue;
		g = os_zalloc(sizeof(*g));
		if (g == NULL) {
			ret = -1;
			break;
		}
		pos2 = NULL;
		pos = str_token(buf, ":", &pos2);
		if (!pos || os_strlen(pos) >= sizeof(g->imsi)) {
			printf("%s:%d - Invalid IMSI\n", fname, line);
			ret = -1;
			break;
		}
		os_strlcpy(g->imsi, pos, sizeof(g->imsi));
		pos = str_token(buf, ":", &pos2);
		if (!pos || os_strlen(pos) != 16 || hexstr2bin(pos, g->kc, 8)) {
			printf("%s:%d - Invalid Kc\n", fname, line);
			ret = -1;
			break;
		}
		pos = str_token(buf, ":", &pos2);
		if (!pos || os_strlen(pos) != 8 ||
		    hexstr2bin(pos, g->sres, 4)) {
			printf("%s:%d - Invalid SRES\n", fname, line);
			ret = -1;
			break;
		}
		pos = str_token(buf, ":", &pos2);
		if (!pos || os_strlen(pos) != 32 ||
		    hexstr2bin(pos, g->_rand, 16)) {
			printf("%s:%d - Invalid RAND\n", fname, line);
			ret = -1;
			break;
		}
		g->next = gsm_db;
		gsm_db = g;
		g = NULL;
	}
	os_free(g);
	fclose(f);
	return ret;
}

static int cmd_doc(ReplState *state, const char *args)
{
    char sym_buf[MAX_VAR_NAME_LEN];
    strncpy(sym_buf, args, sizeof(sym_buf) - 1);
    sym_buf[sizeof(sym_buf) - 1] = 0;
    char *sym = sym_buf;
    while (*sym == ' ')
    {
        sym++;
    }
    size_t symlen = strlen(sym);
    while (symlen > 0 && sym[symlen - 1] == ' ')
    {
        sym[--symlen] = 0;
    }
    const ReplDoc *doc = repl_find_doc(state, sym);
    if (doc)
    {
        printf("\033[1;36m%s\033[0m\n%s\n", doc->name, doc->doc);
        return REPL_HANDLED;
    }
    if (z_is_windows())
    {
        printf("No documentation for '%s'. (Man pages not available on Windows)\n", sym);
        return REPL_HANDLED;
    }
    char safe_sym[MAX_VAR_NAME_LEN];
    size_t slen = strlen(sym);
    if (slen > 255)
    {
        slen = 255;
    }
    strncpy(safe_sym, sym, slen);
    safe_sym[slen] = 0;
    for (int i = 0; safe_sym[i]; i++)
    {
        if (!isalnum((unsigned char)safe_sym[i]) && safe_sym[i] != '_' && safe_sym[i] != ':' &&
            safe_sym[i] != '.')
        {
            safe_sym[i] = '_';
        }
    }
    char man_cmd[MAX_MANGLED_NAME_LEN];
    snprintf(man_cmd, sizeof(man_cmd),
             "man 3 %s 2>/dev/null | sed -n '/^SYNOPSIS/,/^[A-Z]/p' | head -10", safe_sym);
    FILE *mp = popen(man_cmd, "r");
    if (mp)
    {
        char buf[MAX_SHORT_MSG_LEN];
        int lines = 0;
        while (fgets(buf, sizeof(buf), mp) && lines < 8)
        {
            printf("%s", buf);
            lines++;
        }
        int status = pclose(mp);
        if (0 == status && lines > 0)
        {
            printf("\033[90m(man 3 %s)\033[0m\n", sym);
            return REPL_HANDLED;
        }
    }
    printf("No documentation for '%s'.\n", sym);
    return REPL_HANDLED;
}

