static bool write_index_tbl(const int file_num, const char **files)
{
	LOGD("try to write index table...");
	bool ret = false;
	bool foundFdt = false;
	int offset =
	        header.header_size + header.tbl_entry_size * header.tbl_entry_num;
	index_tbl_entry entry;
	char hash[20];	
	int i;
	memcpy(entry.tag, INDEX_TBL_ENTR_TAG, sizeof(entry.tag));
	for (i = 0; i < file_num; i++) {
		size_t file_size = get_file_size(files[i]);
		if (file_size < 0)
			goto end;
		entry.content_size = file_size;
		entry.content_offset = offset;
		if (write_file(offset, files[i], hash, sizeof(hash)) < 0)
			goto end;
		memcpy(entry.hash, hash, sizeof(hash));
		entry.hash_size = sizeof(hash);
		LOGD("try to write index entry(%s)...", files[i]);
		fix_entry(&entry);
		memset(entry.path, 0, sizeof(entry.path));
		const char *path = files[i];
		if (root_path[0]) {
			if (!strncmp(path, root_path, strlen(root_path))) {
				path += strlen(root_path);
				if (path[0] == '/')
					path++;
			}
		}
		path = fix_path(path);
		if (!strcmp(files[i] + strlen(files[i]) - strlen(DTD_SUBFIX), DTD_SUBFIX)) {
			if (!foundFdt) {
				LOGD("mod fdt path:%s -> %s...", files[i], FDT_PATH);
				path = FDT_PATH;
				foundFdt = true;
			}
		}
		snprintf(entry.path, sizeof(entry.path), "%s", path);
		offset += fix_blocks(file_size);
		if (!write_data(header.header_size + i * header.tbl_entry_size, &entry,
		                sizeof(entry)))
			goto end;
	}
	ret = true;
end:
	return ret;
}

static void keyboard_pl050_interrupt(int irq, void *data)
{
    struct keyboard_pl050_pdata_t * pdat = (struct keyboard_pl050_pdata_t *)data;
    static enum decode_state ds = DECODE_STATE_MAKE_CODE;
    static rt_uint32_t kbd_flag = KBD_NUM_LOCK;
    rt_uint8_t status, value;
    status = read8(pdat->virt + KEYBOARD_IIR);
    while(status & (1 << 0))
    {
        value = read8(pdat->virt + KEYBOARD_DATA);
        switch(ds)
        {
        case DECODE_STATE_MAKE_CODE:
            if(value == 0xf0)
            {
                ds = DECODE_STATE_BREAK_CODE;
            }
            else if(value == 0xe0)
            {
                ds = DECODE_STATE_LONG_MAKE_CODE;
            }
            else
            {
                ds = DECODE_STATE_MAKE_CODE;
                if(value == 0x12)
                {
                    kbd_flag |= KBD_LEFT_SHIFT;
                }
                else if(value == 0x59)
                {
                    kbd_flag |= KBD_RIGHT_SHIFT;
                }
                else if(value == 0x14)
                {
                    kbd_flag |= KBD_LEFT_CTRL;
                }
                else if(value == 0x58)
                {
                    if(kbd_flag & KBD_CAPS_LOCK)
                        kbd_flag &= ~KBD_CAPS_LOCK;
                    else
                        kbd_flag |= KBD_CAPS_LOCK;
                }
                else if(value == 0x7e)
                {
                    if(kbd_flag & KBD_SCROLL_LOCK)
                        kbd_flag &= ~KBD_SCROLL_LOCK;
                    else
                        kbd_flag |= KBD_SCROLL_LOCK;
                }
                else if(value == 0x77)
                {
                    if(kbd_flag & KBD_NUM_LOCK)
                        kbd_flag &= ~KBD_NUM_LOCK;
                    else
                        kbd_flag |= KBD_NUM_LOCK;
                }
                else
                {
                    keyboard_report_event(data, kbd_flag, value, KEY_BUTTON_DOWN);
                }
            }
            break;
        case DECODE_STATE_BREAK_CODE:
            if( (value != 0xf0) && (value != 0xe0))
            {
                ds = DECODE_STATE_MAKE_CODE;
                if(value == 0x12)
                {
                    kbd_flag &= ~KBD_LEFT_SHIFT;
                }
                else if(value == 0x59)
                {
                    kbd_flag &= ~KBD_RIGHT_SHIFT;
                }
                else if(value == 0x14)
                {
                    kbd_flag &= ~KBD_LEFT_CTRL;
                }
                else
                {
                    keyboard_report_event(data, kbd_flag, value, KEY_BUTTON_UP);
                }
            }
            else
            {
                ds = DECODE_STATE_BREAK_CODE;
            }
            break;
        case DECODE_STATE_LONG_MAKE_CODE:
            if( value != 0xf0 && value!= 0xe0)
            {
                ds = DECODE_STATE_MAKE_CODE;
                if(value == 0x14)
                {
                    kbd_flag |= KBD_RIGHT_CTRL;
                }
                else
                {
                    keyboard_report_event(data, kbd_flag, value, KEY_BUTTON_DOWN);
                }
            }
            else
            {
                ds = DECODE_STATE_LONG_BREAK_CODE;
            }
            break;
        case DECODE_STATE_LONG_BREAK_CODE:
            if( (value != 0xf0) && (value != 0xe0))
            {
                ds = DECODE_STATE_MAKE_CODE;
                if(value == 0x14)
                {
                    kbd_flag &= ~KBD_RIGHT_CTRL;
                }
                else
                {
                    keyboard_report_event(data, kbd_flag, value, KEY_BUTTON_UP);
                }
            }
            else
            {
                ds = DECODE_STATE_LONG_BREAK_CODE;
            }
            break;
        default:
            ds = DECODE_STATE_MAKE_CODE;
            break;
        }
        status = read8(pdat->virt + KEYBOARD_IIR);
    }
}

static int js_string_compare(JSContext *ctx, JSValue val1, JSValue val2)
{
    JSStringCharBuf buf1, buf2;
    int len, i, res;
    JSString *p1, *p2;
    p1 = get_string_ptr(ctx, &buf1, val1);
    p2 = get_string_ptr(ctx, &buf2, val2);
    len = min_int(p1->len, p2->len);
    for(i = 0; i < len; i++) {
        if (p1->buf[i] != p2->buf[i])
            break;
    }
    if (i != len) {
        int c1, c2;
        c1 = string_get_cp(p1->buf + i);
        c2 = string_get_cp(p2->buf + i);
        if ((c1 < 0x10000 && c2 < 0x10000) ||
            (c1 >= 0x10000 && c2 >= 0x10000)) {
            if (c1 < c2)
                res = -1;
            else
                res = 1;
        } else if (c1 < 0x10000) {
            c2 = 0xd800 + ((c2 - 0x10000) >> 10);
            if (c1 <= c2)
                res = -1;
            else
                res = 1;
        } else {
            c1 = 0xd800 + ((c1 - 0x10000) >> 10);
            if (c1 < c2)
                res = -1;
            else
                res = 1;
        }
    } else {
        if (p1->len == p2->len)
            res = 0;
        else if (p1->len < p2->len)
            res = -1;
        else
            res = 1;
    }
    return res;
}

public void initOptions(CompilerOptions options) {
    this.options = options;
    if (errorManager == null) {
      if (outStream == null) {
        setErrorManager(
            new LoggerErrorManager(createMessageFormatter(), logger));
      } else {
        PrintStreamErrorManager printer =
            new PrintStreamErrorManager(createMessageFormatter(), outStream);
        printer.setSummaryDetailLevel(options.summaryDetailLevel);
        setErrorManager(printer);
      }
    }

    // DiagnosticGroups override the plain checkTypes option.
    if (options.enables(DiagnosticGroups.CHECK_TYPES)) {
      options.checkTypes = true;
    } else if (options.disables(DiagnosticGroups.CHECK_TYPES)) {
      options.checkTypes = false;
    } else if (!options.checkTypes) {
      // If DiagnosticGroups did not override the plain checkTypes
      // option, and checkTypes is enabled, then turn off the
      // parser type warnings.
      options.setWarningLevel(
          DiagnosticGroup.forType(
              RhinoErrorReporter.TYPE_PARSE_ERROR),
          CheckLevel.OFF);
    }

    if (options.checkGlobalThisLevel.isOn()) {
      options.setWarningLevel(
          DiagnosticGroups.GLOBAL_THIS,
          options.checkGlobalThisLevel);
    }

    // Initialize the warnings guard.
    List<WarningsGuard> guards = Lists.newArrayList();
    guards.add(
        new SuppressDocWarningsGuard(
            getDiagnosticGroups().getRegisteredGroups()));
    guards.add(options.getWarningsGuard());

    ComposeWarningsGuard composedGuards = new ComposeWarningsGuard(guards);

    // All passes must run the variable check. This synthesizes
    // variables later so that the compiler doesn't crash. It also
    // checks the externs file for validity. If you don't want to warn
    // about missing variable declarations, we shut that specific
    // error off.
    if (!options.checkSymbols &&
        !composedGuards.enables(DiagnosticGroups.CHECK_VARIABLES)) {
      composedGuards.addGuard(new DiagnosticGroupWarningsGuard(
          DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF));
    }

    this.warningsGuard = composedGuards;
  }

uint8_t CAN_Transmit(CAN_TypeDef* CANx, CanTxMsg* TxMessage)
{
  uint8_t transmit_mailbox = 0;
  assert_param(IS_CAN_ALL_PERIPH(CANx));
  assert_param(IS_CAN_IDTYPE(TxMessage->IDE));
  assert_param(IS_CAN_RTR(TxMessage->RTR));
  assert_param(IS_CAN_DLC(TxMessage->DLC));
  if ((CANx->TSR&CAN_TSR_TME0) != CAN_TSR_TME0)
  {
    transmit_mailbox = 0;
  }
  else if ((CANx->TSR&CAN_TSR_TME1) == CAN_TSR_TME1)
  {
    transmit_mailbox = 1;
  }
  else if ((CANx->TSR&CAN_TSR_TME2) == CAN_TSR_TME2)
  {
    transmit_mailbox = 2;
  }
  else
  {
    transmit_mailbox = CAN_TxStatus_NoMailBox;
  }
  if (transmit_mailbox != CAN_TxStatus_NoMailBox)
  {
    CANx->sTxMailBox[transmit_mailbox].TIR &= TMIDxR_TXRQ;
    if (TxMessage->IDE == CAN_Id_Standard)
    {
      assert_param(IS_CAN_STDID(TxMessage->StdId));  
      CANx->sTxMailBox[transmit_mailbox].TIR |= ((TxMessage->StdId << 21) | \
                                                  TxMessage->RTR);
    }
    else
    {
      assert_param(IS_CAN_EXTID(TxMessage->ExtId));
      CANx->sTxMailBox[transmit_mailbox].TIR |= ((TxMessage->ExtId << 3) | \
                                                  TxMessage->IDE | \
                                                  TxMessage->RTR);
    }
    TxMessage->DLC &= (uint8_t)0x0000000F;
    CANx->sTxMailBox[transmit_mailbox].TDTR &= (uint32_t)0xFFFFFFF0;
    CANx->sTxMailBox[transmit_mailbox].TDTR |= TxMessage->DLC;
    CANx->sTxMailBox[transmit_mailbox].TDLR = (((uint32_t)TxMessage->Data[3] << 24) | 
                                             ((uint32_t)TxMessage->Data[2] << 16) |
                                             ((uint32_t)TxMessage->Data[1] << 8) | 
                                             ((uint32_t)TxMessage->Data[0]));
    CANx->sTxMailBox[transmit_mailbox].TDHR = (((uint32_t)TxMessage->Data[7] << 24) | 
                                             ((uint32_t)TxMessage->Data[6] << 16) |
                                             ((uint32_t)TxMessage->Data[5] << 8) |
                                             ((uint32_t)TxMessage->Data[4]));
    CANx->sTxMailBox[transmit_mailbox].TIR |= TMIDxR_TXRQ;
  }
  return transmit_mailbox;
}

