    addr = addr & 0x3fff;
    uint8_t res = 0;
    if (addr >= 0x3f00) { 
        unsigned palette_ix = g_palette_addr_map[addr & 0x1f];
        res = ppu->palette[palette_ix];
    } else if (addr < 0x2000) { 
        res = mapper_read(ppu->agnes, addr);
    } else { 
        uint16_t mirrored_addr = mirror_address(ppu, addr);
        res = ppu->nametables[mirrored_addr];
    }
    return res;
}

