static void StateEq(float X[NUMX], float U[NUMU], float Xdot[NUMX])
{
	float ax, ay, az, wx, wy, wz, q1, q1, q2, q3;
	ax = U[3];
	ay = U[4];
	az = U[5];		
	wx = U[0] - X[10];
	wy = U[1] - X[11];
	wz = U[2] - X[12];	
	q0 = X[6];
	q1 = X[7];
	q2 = X[8];
	q3 = X[9];
	Xdot[0] = X[3];
	Xdot[1] = X[4];
	Xdot[2] = X[5];
	Xdot[3] =
	    (q0 * q0 + q1 * q1 - q2 * q2 - q3 * q3) * ax + 2.0f * (q1 * q2 -
								q0 * q3) *
	    ay + 2.0f * (q1 * q3 + q0 * q2) * az;
	Xdot[4] =
	    2.0f * (q1 * q2 + q0 * q3) * ax + (q0 * q0 - q1 * q1 + q2 * q2 -
					    q3 * q3) * ay + 2 * (q2 * q3 -
								 q0 * q1) *
	    az;
	Xdot[5] =
	    2.0f * (q1 * q3 - q0 * q2) * ax + 2 * (q2 * q3 + q0 * q1) * ay +
	    (q0 * q0 - q1 * q1 - q2 * q2 + q3 * q3) * az + GRAVITY;
	Xdot[6] = (-q1 * wx - q2 * wy - q3 * wz) / 2.0f;
	Xdot[7] = (q0 * wx - q3 * wy + q2 * wz) / 2.0f;
	Xdot[8] = (q3 * wx + q0 * wy - q1 * wz) / 2.0f;
	Xdot[9] = (-q2 * wx + q1 * wy + q0 * wz) / 2.0f;
	Xdot[10] = Xdot[11] = Xdot[12] = 0;
}

static int decimal_cmp(Decimal *pA, Decimal *pB){
  int nASig, nBSig, rc, n;
  while( pA->nFrac>0 && pA->a[pA->nDigit-1]==0 ){
    pA->nDigit--;
    pA->nFrac--;
  }
  while( pB->nFrac>0 && pB->a[pB->nDigit-1]==0 ){
    pB->nDigit--;
    pB->nFrac--;
  }
  if( pA->sign!=pB->sign ){
    return pA->sign ? -1 : +1;
  }
  if( pA->sign ){
    Decimal *pTemp = pA;
    pA = pB;
    pB = pTemp;
  }
  nASig = pA->nDigit - pA->nFrac;
  nBSig = pB->nDigit - pB->nFrac;
  if( nASig!=nBSig ){
    return nASig - nBSig;
  }
  n = pA->nDigit;
  if( n>pB->nDigit ) n = pB->nDigit;
  rc = memcmp(pA->a, pB->a, n);
  if( rc==0 ){
    rc = pA->nDigit - pB->nDigit;
  }
  return rc;
}

