async function cratesFetch(url, label) {
    let resp;
    try {
        resp = await fetch(url, { headers: { 'user-agent': UA, accept: 'application/json' } });
    }
    catch (err) {
        throw new CommandExecutionError(
            `${label} request failed: ${err?.message ?? err}`,
            'Check that crates.io is reachable from this network.',
        );
    }
    if (resp.status === 404) {
        throw new EmptyResultError(label, `crates.io returned 404 for ${url}.`);
    }
    if (resp.status === 429) {
        throw new CommandExecutionError(
            `${label} returned HTTP 429 (rate limited)`,
            'crates.io rate-limits unauthenticated traffic; wait a few seconds and retry.',
        );
    }
    if (!resp.ok) {
        throw new CommandExecutionError(`${label} returned HTTP ${resp.status}`);
    }
    let body;
    try {
        body = await resp.json();
    }
    catch (err) {
        throw new CommandExecutionError(`${label} returned malformed JSON: ${err?.message ?? err}`);
    }
    return body;
}

void misra_check_file_dereference(struct TypeChecker *tc, struct Type *type, Token tok)
{
    if (!g_config.misra_mode || !type)
    {
        return;
    }
    Type *resolved = resolve_alias(type);
    if (resolved->kind == TYPE_POINTER && resolved->inner)
    {
        Type *inner = resolve_alias(resolved->inner);
        if (inner->kind == TYPE_STRUCT && inner->name && strcmp(inner->name, "FILE") == 0)
