static int dfs_are_channels_overlapped(struct hostapd_iface *iface, int freq,
				       int chan_width, int cf1, int cf2)
{
	int start_chan_idx, start_chan_idx1;
	struct hostapd_hw_modes *mode;
	struct hostapd_channel_data *chan;
	int n_chans, n_chans1, i, j, frequency = freq, radar_n_chans = 1;
	u8 radar_chan;
	int res = 0;
	mode = iface->current_mode;
	start_chan_idx = dfs_get_start_chan_idx(iface, &start_chan_idx1);
	n_chans = dfs_get_used_n_chans(iface, &n_chans1);
	if (!dfs_check_chans_radar(iface, start_chan_idx, n_chans))
		return 0;
	switch (chan_width) {
	case CHAN_WIDTH_20_NOHT:
	case CHAN_WIDTH_20:
		radar_n_chans = 1;
		if (frequency != 0)
			frequency = cf1;
		break;
	case CHAN_WIDTH_40:
		radar_n_chans = 2;
		frequency = cf1 - 10;
		break;
	case CHAN_WIDTH_80:
		radar_n_chans = 4;
		frequency = cf1 - 30;
		break;
	case CHAN_WIDTH_160:
		radar_n_chans = 8;
		frequency = cf1 - 70;
		break;
	default:
		wpa_printf(MSG_INFO, "DFS chan_width %d not supported",
			   chan_width);
		break;
	}
	ieee80211_freq_to_chan(frequency, &radar_chan);
	for (i = 0; i < n_chans; i++) {
		chan = &mode->channels[start_chan_idx + i];
		if (!(chan->flag & HOSTAPD_CHAN_RADAR))
			continue;
		for (j = 0; j < radar_n_chans; j++) {
			wpa_printf(MSG_DEBUG, "checking our: %d, radar: %d",
				   chan->chan, radar_chan + j * 4);
			if (chan->chan == radar_chan + j * 4)
				res++;
		}
	}
	wpa_printf(MSG_DEBUG, "overlapped: %d", res);
	return res;
}

uint16_t fp32_to_fp16(float f) {
    uint32_t bits;
    memcpy(&bits, &f, sizeof(float));
    uint32_t sign = (bits >> 16) & 0x8000;
    int      exp  = (int)((bits >> 23) & 0xFF) - 127 + 15;
    uint32_t mant = bits & 0x7FFFFF;
    if (((bits >> 23) & 0xFF) == 0) {
        return (uint16_t)sign; 
    }
    if (((bits >> 23) & 0xFF) == 0xFF) {
        return (uint16_t)(sign | 0x7C00 | (mant ? 0x0200 : 0));
    }
    if (exp >= 31) {
        return (uint16_t)(sign | 0x7C00); 
    }
    if (exp <= 0) {
        if (exp < -10) return (uint16_t)sign; 
        mant |= 0x800000;
        uint32_t shift = (uint32_t)(14 - exp);
        uint32_t round_bit = 1U << (shift - 1);
        mant = (mant + round_bit) >> shift;
        return (uint16_t)(sign | mant);
    }
    mant += 0x00001000; 
    if (mant & 0x00800000) {
        mant = 0;
        exp++;
        if (exp >= 31) return (uint16_t)(sign | 0x7C00);
    }
    return (uint16_t)(sign | ((uint32_t)exp << 10) | (mant >> 13));
}

static EFI_STATUS get_memory_map(void)
{
    EFI_STATUS status;
    memory_map_size = 0;
    status = gBS->GetMemoryMap(&memory_map_size, NULL, &memory_map_key,
                                &descriptor_size, &descriptor_version);
    memory_map_size += 4 * descriptor_size;
    status = gBS->AllocatePages(0, EfiLoaderData,
                                 (memory_map_size + 4095) / 4096,
                                 (EFI_PHYSICAL_ADDRESS *)&memory_map);
    if (status != EFI_SUCCESS) {
        efi_print("Failed to allocate memory for memory map\r\n");
        return status;
    }
    status = gBS->GetMemoryMap(&memory_map_size, memory_map, &memory_map_key,
                                &descriptor_size, &descriptor_version);
    if (status != EFI_SUCCESS) {
        efi_print("Failed to get memory map\r\n");
        return status;
    }
    return EFI_SUCCESS;
}

