function blackman(x, fcn, l) {
    var wcn = (Math.PI * fcn);
    x /= l;
    if (x < 0)
        x = 0;
    if (x > 1)
        x = 1;
    var x2 = x - .5;
    var bkwn = 0.42 - 0.5 * Math.cos(2 * x * Math.PI) + 0.08 * Math.cos(4 * x * Math.PI);
    if (Math.abs(x2) < 1e-9)
        return (wcn / Math.PI);
    else
        return (bkwn * Math.sin(l * wcn * x2) / (Math.PI * l * x2));
}

int WMM_AssociatedLegendreFunction(WMMtype_CoordSpherical * CoordSpherical, uint16_t nMax, WMMtype_LegendreFunction * LegendreFunction)
{
	float sin_phi = sinf(CoordSpherical->phig * DEG2RAD);	
	if (nMax <= 16 || (1 - fabsf(sin_phi)) >= 1.0e-10f)	
	{
		if (WMM_PcupLow(LegendreFunction->Pcup, LegendreFunction->dPcup, sin_phi, nMax) < 0)
		    return -1;  
	}
	else
	{
		if (WMM_PcupHigh(LegendreFunction->Pcup, LegendreFunction->dPcup, sin_phi, nMax) < 0)
		    return -2;  
	}
	return 0;   
}

