      }
      const passes = a.pairs.filter(p => p.level !== 'FAIL');
      if (passes.length > 0) {
        lines.push('### Passing Color Pairs');
        lines.push('');
        lines.push('| Foreground | Background | Ratio | Level |');
        lines.push('|------------|------------|-------|-------|');
