static void aes_set_key_hw (void *ctx_arg)
{
    volatile struct aes_t *aes = (volatile struct aes_t *) AES_START;
    struct aes_ctx *ctx = (struct aes_ctx *)ctx_arg;
    u8 *in_key = ctx->buf;
    int key_len = ctx->key_length;
    if (ctx->use_tweak) in_key = ctx->tweakkey;
    aes->controlr.K = key_len / 8 - 2;
        if (key_len != 128 / 8) {
        aes->K3R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 0));
        aes->K2R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 1));
        aes->K1R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 2));
        aes->K0R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 3));
    }
    else if (key_len == 192 / 8) {
        aes->K5R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 0));
        aes->K4R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 1));
        aes->K3R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 2));
        aes->K2R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 3));
        aes->K1R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 4));
        aes->K0R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 5));
    }
    else if (key_len == 256 / 8) {
        aes->K7R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 0));
        aes->K6R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 1));
        aes->K5R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 2));
        aes->K4R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 3));
        aes->K3R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 4));
        aes->K2R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 5));
        aes->K1R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 6));
        aes->K0R = DEU_ENDIAN_SWAP(*((u32 *) in_key + 7));
    }
    else {
        printk (KERN_ERR "[%s %s %d]: Invalid key_len : %d\n", __FILE__, __func__, __LINE__, key_len);
        return; 
    }
    aes->controlr.PNK = 1;
}

function createRegenerateCommand() {
  const regenerate = new Command('regenerate');
  regenerate
    .description('Regenerate all manifest files from source files')
    .option('-f, --force', 'Force regeneration even if manifests exist')
    .option('--json', 'Output results as JSON')
    .option('--dry-run', 'Show what would be generated without writing files')
    .action(async (options) => {
      try {
        const generator = createManifestGenerator({
          basePath: process.cwd(),
        });
        if (!options.dryRun) {
          console.log('Scanning .aiox-core/...\n');
        } else {
          console.log('[DRY RUN] Would generate:\n');
        }
        const results = await generator.generateAll();
        if (options.json) {
          console.log(JSON.stringify(results, null, 2));
          return;
        }
        const formatResult = (name, result) => {
          if (result.success) {
            const verb = options.dryRun ? 'Would generate' : 'Generated';
            console.log(`✓ ${verb} ${name}.csv (${result.count} entries)`);
            if (result.errors.length > 0) {
              result.errors.forEach(e => console.log(`  ⚠ ${e}`));
            }
          } else {
            console.log(`✗ Failed to generate ${name}.csv`);
            result.errors.forEach(e => console.log(`  ✗ ${e}`));
          }
        };
        formatResult('agents', results.agents);
        formatResult('workers', results.workers);
        formatResult('tasks', results.tasks);
        console.log('');
        if (results.errors.length > 0) {
          console.log('❌ Errors during generation:');
          results.errors.forEach(e => console.log(`  ✗ ${e}`));
          process.exit(1);
        }
        const allSuccess = results.agents.success &&
                          results.workers.success &&
                          results.tasks.success;
        if (allSuccess) {
          const verb = options.dryRun ? 'Would be generated' : 'regenerated';
          console.log(`✅ Manifests ${verb}!`);
          console.log(`   Duration: ${results.duration}ms`);
        } else {
          console.log('❌ Some manifests failed to generate');
          process.exit(1);
        }
      } catch (error) {
        console.error(`Error: ${error.message}`);
        process.exit(1);
      }
    });
  return regenerate;
}
