function parseCommand(cmdString) {
  if (typeof cmdString !== 'string') {
    throw new Error('command must be a string, got ' + typeof cmdString);
  }
  const tokens = [];
  let buf = '';
  let quote = null; 
  for (let i = 0; i < cmdString.length; i++) {
    const ch = cmdString[i];
    if (quote) {
      if (ch === quote) {
        quote = null;
      } else {
        buf += ch;
      }
      continue;
    }
    if (ch === '\'' || ch === '"') {
      quote = ch;
      continue;
    }
    if (ch === ' ' || ch === '\t' || ch === '\n') {
      if (buf.length > 0) {
        tokens.push(buf);
        buf = '';
      }
      continue;
    }
    if (ch === '|' || ch === '&' || ch === ';' || ch === '>' || ch === '<' || ch === '`' || ch === '$') {
      throw new Error('shell metacharacter not allowed in command: ' + ch);
    }
    buf += ch;
  }
  if (quote) throw new Error('unterminated quote in command');
  if (buf.length > 0) tokens.push(buf);
  if (tokens.length === 0) throw new Error('empty command');
  return { executable: tokens[0], args: tokens.slice(1) };
}

int Set_Polar_Stereographic_Parameters (double a,
                                         double f,
                                         double Latitude_of_True_Scale,
                                         double longitude_Down_from_Pole,
                                         double False_Easting,
                                         double False_Northing)
{  
  double es2;
  double slat, clat;
  double essin;
  double one_PLUS_es, one_MINUS_es;
  double pow_es;
  double temp, temp_northing;
  double inv_f = 1 / f;
  double mc;                    
  int Error_Code = POLAR_NO_ERROR;
  if (a <= 0.0)
  { 
    Error_Code |= POLAR_A_ERROR;
  }
  if ((inv_f < 250) || (inv_f > 350))
  { 
    Error_Code |= POLAR_INV_F_ERROR;
  }
  if ((Latitude_of_True_Scale < -PI_OVER_2) || (Latitude_of_True_Scale > PI_OVER_2))
  { 
    Error_Code |= POLAR_ORIGIN_LAT_ERROR;
  }
  if ((longitude_Down_from_Pole < -PI) || (longitude_Down_from_Pole > TWO_PI))
  { 
    Error_Code |= POLAR_ORIGIN_LON_ERROR;
  }
  if (!Error_Code)
  { 
    Polar_a = a;
    two_Polar_a = 2.0 * Polar_a;
    Polar_f = f;
    if (longitude_Down_from_Pole > PI)
      longitude_Down_from_Pole -= TWO_PI;
    if (Latitude_of_True_Scale < 0)
    {
      Southern_Hemisphere = 1;
      Polar_Origin_Lat = -Latitude_of_True_Scale;
      Polar_Origin_int = -longitude_Down_from_Pole;
    }
    else
    {
      Southern_Hemisphere = 0;
      Polar_Origin_Lat = Latitude_of_True_Scale;
      Polar_Origin_int = longitude_Down_from_Pole;
    }
    Polar_False_Easting = False_Easting;
    Polar_False_Northing = False_Northing;
    es2 = 2 * Polar_f - Polar_f * Polar_f;
    es = sqrt(es2);
    es_OVER_2 = es / 2.0;
    if (fabs(fabs(Polar_Origin_Lat) - PI_OVER_2) > 1.0e-10)
    {
      slat = sin(Polar_Origin_Lat);
      essin = es * slat;
      pow_es = POLAR_POW(essin);
      clat = cos(Polar_Origin_Lat);
      mc = clat / sqrt(1.0 - essin * essin);
      Polar_a_mc = Polar_a * mc;
      tc = tan(PI_Over_4 - Polar_Origin_Lat / 2.0) / pow_es;
    }
    else
    {
      one_PLUS_es = 1.0 + es;
      one_MINUS_es = 1.0 - es;
      e4 = sqrt(pow(one_PLUS_es, one_PLUS_es) * pow(one_MINUS_es, one_MINUS_es));
    }
    Convert_Geodetic_To_Polar_Stereographic(0, longitude_Down_from_Pole, 
                                            &temp, &temp_northing);
    Polar_Delta_Northing = temp_northing;
    if(Polar_False_Northing)
      Polar_Delta_Northing -= Polar_False_Northing;
    if (Polar_Delta_Northing < 0)
      Polar_Delta_Northing = -Polar_Delta_Northing;
    Polar_Delta_Northing *= 1.01;
    Polar_Delta_Easting = Polar_Delta_Northing;
  }
  return (Error_Code);
}

static void FirmwareIAPCallback(const UAVObjEvent *ev,
		void *ctx, void *obj, int len)
{
	(void) ctx; (void) obj; (void) len;
	static uint8_t    iap_state = IAP_STATE_READY;
	static uint32_t   last_time = 0;
	uint32_t          this_time;
	uint32_t          delta;
	if(iap_state == IAP_STATE_RESETTING)
		return;
	FirmwareIAPObjData data;
	FirmwareIAPObjGet(&data);
	if ( ev->obj == FirmwareIAPObjHandle() )	{
		FirmwareIAPObjGet(&data);
		this_time = get_time();
		delta = this_time - last_time;
		last_time = this_time;
		switch(iap_state) {
			case IAP_STATE_READY:
				if( data.Command == IAP_CMD_STEP_1 ) {
					iap_state = IAP_STATE_STEP_1;
				}            break;
			case IAP_STATE_STEP_1:
				if( data.Command == IAP_CMD_STEP_2 ) {
					if( delta > iap_time_2_low_end && delta < iap_time_2_high_end ) {
						iap_state = IAP_STATE_STEP_2;
					} else {
						iap_state = IAP_STATE_READY;
					}
				} else {
					iap_state = IAP_STATE_READY;
				}
				break;
			case IAP_STATE_STEP_2:
				if( (data.Command == IAP_CMD_STEP_3) || (data.Command == IAP_CMD_STEP_3NB) ) {
					if( delta > iap_time_3_low_end && delta < iap_time_3_high_end ) {
						FlightStatusData flightStatus;
						FlightStatusGet(&flightStatus);
						if(flightStatus.Armed != FLIGHTSTATUS_ARMED_DISARMED) {
							iap_state = IAP_STATE_READY;
							break;
						}
						if(data.Command == IAP_CMD_STEP_3) {
							PIOS_IAP_SetRequest1();
							PIOS_IAP_SetRequest2();
						}
						else if(data.Command == IAP_CMD_STEP_3NB) {
							PIOS_IAP_SetRequest1();
							PIOS_IAP_SetRequest3();
						}
						reset_count = 0;
						lastResetSysTime = PIOS_Thread_Systime();
						UAVObjEvent * ev = PIOS_malloc_no_dma(sizeof(UAVObjEvent));
						memset(ev,0,sizeof(UAVObjEvent));
						EventPeriodicCallbackCreate(ev, resetTask, 100);
						PIOS_Servo_PrepareForReset(); 
						iap_state = IAP_STATE_RESETTING;
					} else {
						iap_state = IAP_STATE_READY;
					}
				} else {
					iap_state = IAP_STATE_READY;
				}
				break;
			case IAP_STATE_RESETTING:
				break;
			default:
				iap_state = IAP_STATE_READY;
				last_time = 0; 
				break;
		}
	}
}

static void winMemShutdown(void *pAppData){
  winMemData *pWinMemData = (winMemData *)pAppData;
  if( !pWinMemData ) return;
  assert( pWinMemData->magic1==WINMEM_MAGIC1 );
  assert( pWinMemData->magic2==WINMEM_MAGIC2 );
  if( pWinMemData->hHeap ){
    assert( pWinMemData->hHeap!=INVALID_HANDLE_VALUE );
#if !SQLITE_OS_WINRT || defined(SQLITE_WIN32_MALLOC_VALIDATE)
    assert( osHeapValidate(pWinMemData->hHeap, SQLITE_WIN32_HEAP_FLAGS, NULL) );
#endif
    if( pWinMemData->bOwned ){
      if( !osHeapDestroy(pWinMemData->hHeap) ){
        sqlite3_log(SQLITE_NOMEM, "failed to HeapDestroy (%lu), heap=%p",
                    osGetLastError(), (void*)pWinMemData->hHeap);
      }
      pWinMemData->bOwned = FALSE;
    }
    pWinMemData->hHeap = NULL;
  }
}

