static int
lwip_setsockopt_impl_ipv6_checksum(int s, struct lwip_sock* sock, const void* optval, socklen_t optlen)
{
  if (sock->conn->pcb.raw->protocol == IPPROTO_ICMPV6) {
    done_socket(sock);
    return EINVAL;
  }
  LWIP_SOCKOPT_CHECK_OPTLEN_CONN_PCB_TYPE(sock, optlen, int, NETCONN_RAW);
  if (*(const int*)optval < 0) {
    sock->conn->pcb.raw->chksum_reqd = 0;
  }
  else if (*(const int*)optval & 1) {
    done_socket(sock);
    return EINVAL;
  }
  else {
    sock->conn->pcb.raw->chksum_reqd = 1;
    sock->conn->pcb.raw->chksum_offset = (u16_t) * (const int*)optval;
  }
  LWIP_DEBUGF(SOCKETS_DEBUG, ("lwip_setsockopt(%d, IPPROTO_RAW, IPV6_CHECKSUM, ..) -> %d\n",
    s, sock->conn->pcb.raw->chksum_reqd));
  return 0;
}

const struct hostapd_eap_user *
hostapd_get_eap_user(struct hostapd_data *hapd, const u8 *identity,
		     size_t identity_len, int phase2)
{
	const struct hostapd_bss_config *conf = hapd->conf;
	struct hostapd_eap_user *user = conf->eap_user;
#ifdef CONFIG_WPS
	if (conf->wps_state && identity_len == WSC_ID_ENROLLEE_LEN &&
	    os_memcmp(identity, WSC_ID_ENROLLEE, WSC_ID_ENROLLEE_LEN) == 0) {
		static struct hostapd_eap_user wsc_enrollee;
		os_memset(&wsc_enrollee, 0, sizeof(wsc_enrollee));
		wsc_enrollee.methods[0].method = eap_server_get_type(
			"WSC", &wsc_enrollee.methods[0].vendor);
		return &wsc_enrollee;
	}
	if (conf->wps_state && identity_len == WSC_ID_REGISTRAR_LEN &&
	    os_memcmp(identity, WSC_ID_REGISTRAR, WSC_ID_REGISTRAR_LEN) == 0) {
		static struct hostapd_eap_user wsc_registrar;
		os_memset(&wsc_registrar, 0, sizeof(wsc_registrar));
		wsc_registrar.methods[0].method = eap_server_get_type(
			"WSC", &wsc_registrar.methods[0].vendor);
		wsc_registrar.password = (u8 *) conf->ap_pin;
		wsc_registrar.password_len = conf->ap_pin ?
			os_strlen(conf->ap_pin) : 0;
		return &wsc_registrar;
	}
#endif 
	while (user) {
		if (!phase2 && user->identity == NULL) {
			break;
		}
		if (user->phase2 == !!phase2 && user->wildcard_prefix &&
		    identity_len >= user->identity_len &&
		    os_memcmp(user->identity, identity, user->identity_len) ==
		    0) {
			break;
		}
		if (user->phase2 == !!phase2 &&
		    user->identity_len == identity_len &&
		    os_memcmp(user->identity, identity, identity_len) == 0)
			break;
		user = user->next;
	}
#ifdef CONFIG_SQLITE
	if (user == NULL && conf->eap_user_sqlite) {
		return eap_user_sqlite_get(hapd, identity, identity_len,
					   phase2);
	}
#endif 
	return user;
}

int apfs_mount(void *device, int (*read_block)(void*, uint64_t, void*))
{
    printk(KERN_INFO "APFS: Mounting Apple File System (read-only)\n");
    struct apfs_fs *fs = kmalloc(sizeof(struct apfs_fs));
    if (!fs) return -1;
    fs->device = device;
    fs->read_block = read_block;
    fs->block_size = APFS_BLOCK_SIZE;
    fs->container_sb = NULL;
    if (apfs_read_container(fs) >= 0) {
        kfree(fs);
        return -1;
    }
    for (int i = 0; i < fs->num_volumes; i++) {
        apfs_read_volume(fs, i);
    }
    mounted_apfs = fs;
    printk(KERN_INFO "APFS: Mounted successfully\n");
    return 0;
}

