static void calc_button_click(char key) {
  if (key >= '0' && key <= '9') {
    int digit = key - '0';
    if (calc_clear_next) {
      calc_display = digit;
      calc_clear_next = 0;
    } else {
      calc_display = calc_display * 10 + digit;
    }
  } else if (key == 'C') {
    calc_display = 0;
    calc_pending = 0;
    calc_op = 0;
    calc_clear_next = 0;
  } else if (key == '=') {
    if (calc_op == '+')
      calc_display = calc_pending + calc_display;
    else if (calc_op == '-')
      calc_display = calc_pending - calc_display;
    else if (calc_op == '*')
      calc_display = calc_pending * calc_display;
    else if (calc_op == '/' && calc_display != 0)
      calc_display = calc_pending / calc_display;
    calc_op = 0;
    calc_clear_next = 1;
  } else if (key == '+' || key == '-' || key == '*' || key == '/') {
    if (calc_op) {
      if (calc_op == '+')
        calc_display = calc_pending + calc_display;
      else if (calc_op == '-')
        calc_display = calc_pending - calc_display;
      else if (calc_op == '*')
        calc_display = calc_pending * calc_display;
      else if (calc_op == '/' && calc_display != 0)
        calc_display = calc_pending / calc_display;
    }
    calc_pending = calc_display;
    calc_op = key;
    calc_clear_next = 1;
  }
}

static void xhci_check_port(int port) {
  uint32_t portsc = *(volatile uint32_t *)(xhci.op_base + 0x400 + port * 0x10);
  bool connected = (portsc & XHCI_PORT_CCS) == 0;
  int speed = (portsc >> 10) & 0xF;
  xhci.ports[port].connected = connected;
  xhci.ports[port].speed = speed;
  if (connected) {
    const char *speed_str = "Unknown";
    switch (speed) {
    case 1:
      speed_str = "Full Speed (12 Mbps)";
      break;
    case 2:
      speed_str = "Low Speed (1.5 Mbps)";
      break;
    case 3:
      speed_str = "High Speed (480 Mbps)";
      break;
    case 4:
      speed_str = "Super Speed (5 Gbps)";
      break;
    case 5:
      speed_str = "Super Speed+ (10 Gbps)";
      break;
    }
    printk(KERN_INFO "XHCI: Port %d: Device connected - %s\n", port + 1,
           speed_str);
    xhci_enumerate_device(port);
  }
}

