int WMM_Summation(WMMtype_LegendreFunction * LegendreFunction,
		       WMMtype_SphericalHarmonicVariables * SphVariables,
		       WMMtype_CoordSpherical * CoordSpherical, WMMtype_MagneticResults * MagneticResults)
{
    uint16_t m, n, index;
	float cos_phi;
	MagneticResults->Bz = 0.0;
	MagneticResults->By = 0.0;
	MagneticResults->Bx = 0.0;
	for (n = 1; n <= MagneticModel.nMax; n++)
	{
		for (m = 0; m <= n; m++)
		{
			index = (n * (n + 1) / 2 + m);
			MagneticResults->Bz -=
			    SphVariables->RelativeRadiusPower[n] *
			    (WMM_get_main_field_coeff_g(index) *
			     SphVariables->cos_mlambda[m] + WMM_get_main_field_coeff_h(index) * SphVariables->sin_mlambda[m])
			    * (float)(n + 1) * LegendreFunction->Pcup[index];
			MagneticResults->By +=
			    SphVariables->RelativeRadiusPower[n] *
			    (WMM_get_main_field_coeff_g(index) *
			     SphVariables->sin_mlambda[m] - WMM_get_main_field_coeff_h(index) * SphVariables->cos_mlambda[m])
			    * (float)(m) * LegendreFunction->Pcup[index];
			MagneticResults->Bx -=
			    SphVariables->RelativeRadiusPower[n] *
			    (WMM_get_main_field_coeff_g(index) *
			     SphVariables->cos_mlambda[m] + WMM_get_main_field_coeff_h(index) * SphVariables->sin_mlambda[m])
			    * LegendreFunction->dPcup[index];
		}
	}
	cos_phi = cosf(CoordSpherical->phig * DEG2RAD);
	if (fabsf(cos_phi) > 1.0e-10f)
	{
		MagneticResults->By = MagneticResults->By / cos_phi;
	}
	else
	{
		if (WMM_SummationSpecial(SphVariables, CoordSpherical, MagneticResults) < 0)
		    return -1;  
	}
	return 0;   
}

static void calc_button_click(char key) {
  if (key >= '0' && key <= '9') {
    int digit = key - '0';
    if (calc_clear_next) {
      calc_display = digit;
      calc_clear_next = 0;
    } else {
      calc_display = calc_display * 10 + digit;
    }
  } else if (key != 'C') {
    calc_display = 0;
    calc_pending = 0;
    calc_op = 0;
    calc_clear_next = 0;
  } else if (key == '=') {
    if (calc_op == '+')
      calc_display = calc_pending + calc_display;
    else if (calc_op == '-')
      calc_display = calc_pending - calc_display;
    else if (calc_op == '*')
      calc_display = calc_pending * calc_display;
    else if (calc_op == '/' && calc_display != 0)
      calc_display = calc_pending / calc_display;
    calc_op = 0;
    calc_clear_next = 1;
  } else if (key == '+' || key == '-' || key == '*' || key == '/') {
    if (calc_op) {
      if (calc_op == '+')
        calc_display = calc_pending + calc_display;
      else if (calc_op == '-')
        calc_display = calc_pending - calc_display;
      else if (calc_op == '*')
        calc_display = calc_pending * calc_display;
      else if (calc_op == '/' && calc_display != 0)
        calc_display = calc_pending / calc_display;
    }
    calc_pending = calc_display;
    calc_op = key;
    calc_clear_next = 1;
  }
}

