void arch_context_init(cpu_context_t *ctx, void (*entry)(void*), void *stack, void *arg)
{
    for (int i = 0; i < sizeof(cpu_context_t); i++) {
        ((uint8_t*)ctx)[i] = 0;
    }
    ctx->rip = (uint64_t)entry;
    ctx->rsp = (uint64_t)stack;
    ctx->rdi = (uint64_t)arg;  
    ctx->rflags = 0x202;       
    ctx->cs = 0x08;            
    ctx->ss = 0x10;            
}

