static inline void
_hev_rbtree_erase_color (HevRBTree *self, HevRBTreeNode *parent)
{
    HevRBTreeNode *node = NULL, *sibling, *tmp1, *tmp2;
    while (1) {
        sibling = parent->right;
        if (node != sibling) { 
            if (hev_rbtree_node_is_red (sibling)) {
                tmp1 = sibling->left;
                parent->right = tmp1;
                sibling->left = parent;
                hev_rbtree_node_set_parent_color (tmp1, parent,
                                                  HEV_RBTREE_BLACK);
                hev_rbtree_rotate_set_parents (self, parent, sibling,
                                               HEV_RBTREE_RED);
                sibling = tmp1;
            }
            tmp1 = sibling->right;
            if (!tmp1 || hev_rbtree_node_is_black (tmp1)) {
                tmp2 = sibling->left;
                if (!tmp2 || hev_rbtree_node_is_black (tmp2)) {
                    hev_rbtree_node_set_parent_color (sibling, parent,
                                                      HEV_RBTREE_RED);
                    if (hev_rbtree_node_is_red (parent))
                        hev_rbtree_node_set_black (parent);
                    else {
                        node = parent;
                        parent = hev_rbtree_node_parent (node);
                        if (parent)
                            continue;
                    }
                    break;
                }
                tmp1 = tmp2->right;
                sibling->left = tmp1;
                tmp2->right = sibling;
                parent->right = tmp2;
                if (tmp1)
                    hev_rbtree_node_set_parent_color (tmp1, sibling,
                                                      HEV_RBTREE_BLACK);
                tmp1 = sibling;
                sibling = tmp2;
            }
            tmp2 = sibling->left;
            parent->right = tmp2;
            sibling->left = parent;
            hev_rbtree_node_set_parent_color (tmp1, sibling, HEV_RBTREE_BLACK);
            if (tmp2)
                hev_rbtree_node_set_parent (tmp2, parent);
            hev_rbtree_rotate_set_parents (self, parent, sibling,
                                           HEV_RBTREE_BLACK);
            break;
        } else {
            sibling = parent->left;
            if (hev_rbtree_node_is_red (sibling)) {
                tmp1 = sibling->right;
                parent->left = tmp1;
                sibling->right = parent;
                hev_rbtree_node_set_parent_color (tmp1, parent,
                                                  HEV_RBTREE_BLACK);
                hev_rbtree_rotate_set_parents (self, parent, sibling,
                                               HEV_RBTREE_RED);
                sibling = tmp1;
            }
            tmp1 = sibling->left;
            if (!tmp1 || hev_rbtree_node_is_black (tmp1)) {
                tmp2 = sibling->right;
                if (!tmp2 || hev_rbtree_node_is_black (tmp2)) {
                    hev_rbtree_node_set_parent_color (sibling, parent,
                                                      HEV_RBTREE_RED);
                    if (hev_rbtree_node_is_red (parent))
                        hev_rbtree_node_set_black (parent);
                    else {
                        node = parent;
                        parent = hev_rbtree_node_parent (node);
                        if (parent)
                            continue;
                    }
                    break;
                }
                tmp1 = tmp2->left;
                sibling->right = tmp1;
                tmp2->left = sibling;
                parent->left = tmp2;
                if (tmp1)
                    hev_rbtree_node_set_parent_color (tmp1, sibling,
                                                      HEV_RBTREE_BLACK);
                tmp1 = sibling;
                sibling = tmp2;
            }
            tmp2 = sibling->right;
            parent->left = tmp2;
            sibling->right = parent;
            hev_rbtree_node_set_parent_color (tmp1, sibling, HEV_RBTREE_BLACK);
            if (tmp2)
                hev_rbtree_node_set_parent (tmp2, parent);
            hev_rbtree_rotate_set_parents (self, parent, sibling,
                                           HEV_RBTREE_BLACK);
            break;
        }
    }
}

