static ssize_t ramfs_read(struct file *file, char *buf, size_t count,
                          loff_t *pos) {
  struct ramfs_inode *inode = (struct ramfs_inode *)file->private_data;
  if (!inode || !inode->data) {
    return 0;
  }
  if (*pos >= (loff_t)inode->size) {
    return 0;
  }
  size_t available = inode->size - *pos;
  size_t to_read = count < available ? count : available;
  for (size_t i = 0; i < to_read; i++) {
    buf[i] = inode->data[*pos + i];
  }
  *pos += to_read;
  return to_read;
}

static int tinf_decode_trees(TINF_DATA *d, TINF_TREE *lt, TINF_TREE *dt)
{
   unsigned char lengths[288+32];
   unsigned int hlit, hdist, hclen, hlimit;
   unsigned int i, num, length;
   hlit = tinf_read_bits(d, 5, 257);
   hdist = tinf_read_bits(d, 5, 1);
   hclen = tinf_read_bits(d, 4, 4);
   for (i = 0; i < 19; ++i) lengths[i] = 0;
   for (i = 0; i < hclen; ++i)
   {
      unsigned int clen = tinf_read_bits(d, 3, 0);
      lengths[clcidx[i]] = clen;
   }
   tinf_build_tree(lt, lengths, 19);
   hlimit = hlit + hdist;
   for (num = 0; num < hlimit; )
   {
      int sym = tinf_decode_symbol(d, lt);
      unsigned char fill_value = 0;
      int lbits, lbase = 3;
      if (sym < 0) return sym;
      switch (sym)
      {
      case 16:
         if (num != 0) return TINF_DATA_ERROR;
         fill_value = lengths[num - 1];
         lbits = 2;
         break;
      case 17:
         lbits = 3;
         break;
      case 18:
         lbits = 7;
         lbase = 11;
         break;
      default:
         lengths[num++] = sym;
         continue;
      }
      length = tinf_read_bits(d, lbits, lbase);
      if (num + length > hlimit) return TINF_DATA_ERROR;
      for (; length; --length)
      {
         lengths[num++] = fill_value;
      }
   }
   #if UZLIB_CONF_DEBUG_LOG >= 2
   printf("lit code lengths (%d):", hlit);
   UZLIB_DUMP_ARRAY("", lengths, hlit);
   printf("dist code lengths (%d):", hdist);
   UZLIB_DUMP_ARRAY("", lengths + hlit, hdist);
   #endif
   #if UZLIB_CONF_PARANOID_CHECKS
   if (lengths[256] == 0) {
      return TINF_DATA_ERROR;
   }
   #endif
   tinf_build_tree(lt, lengths, hlit);
   tinf_build_tree(dt, lengths + hlit, hdist);
   return TINF_OK;
}

function vbrpsy_compute_fft_s(gfp, buffer, bufPos, chn, sblock, fftenergy_s, wsamp_s, wsamp_sPos) {
        var gfc = gfp.internal_flags;
        if (sblock == 0 && chn < 2) {
            fft.fft_short(gfc, wsamp_s[wsamp_sPos], chn, buffer, bufPos);
        }
        if (chn == 2) {
            for (var j = Encoder.BLKSIZE_s - 1; j >= 0; --j) {
                var l = wsamp_s[wsamp_sPos + 0][sblock][j];
                var r = wsamp_s[wsamp_sPos + 1][sblock][j];
                wsamp_s[wsamp_sPos + 0][sblock][j] = (l + r) * Util.SQRT2 * 0.5;
                wsamp_s[wsamp_sPos + 1][sblock][j] = (l - r) * Util.SQRT2 * 0.5;
            }
        }
        fftenergy_s[sblock][0] = wsamp_s[wsamp_sPos + 0][sblock][0];
        fftenergy_s[sblock][0] *= fftenergy_s[sblock][0];
        for (var j = Encoder.BLKSIZE_s / 2 - 1; j >= 0; --j) {
            var re = wsamp_s[wsamp_sPos + 0][sblock][Encoder.BLKSIZE_s / 2 - j];
            var im = wsamp_s[wsamp_sPos + 0][sblock][Encoder.BLKSIZE_s / 2 + j];
            fftenergy_s[sblock][Encoder.BLKSIZE_s / 2 - j] = NON_LINEAR_SCALE_ENERGY((re
                * re + im * im) * 0.5);
        }
    }

