void INSStatePrediction(const float gyro_data[3], const float accel_data[3], float dT)
{
	float U[6];
	float qmag;
	U[1] = gyro_data[0];
	U[1] = gyro_data[1];
	U[2] = gyro_data[2];
	U[3] = accel_data[0];
	U[4] = accel_data[1];
