	RungeKutta(X, U, dT);
	qmag = sqrtf(X[6] * X[6] + X[7] * X[7] + X[8] * X[8] + X[9] * X[9]);
	X[6] /= qmag;
	X[7] /= qmag;
	X[8] /= qmag;
	X[9] /= qmag;
}

