	if (os_strstr(capab, "[LSIG-TXOP-PROT]"))
		conf->ht_capab |= HT_CAP_INFO_LSIG_TXOP_PROTECT_SUPPORT;
	return 0;
}

void gl_draw_triangle(GLContext *c,
                      GLVertex *p0,GLVertex *p1,GLVertex *p2)
{
  int co,c_and,cc[3],front;
  float norm;
  cc[0]=p0->clip_code;
  cc[1]=p1->clip_code;
  cc[2]=p2->clip_code;
  co=cc[0] | cc[1] | cc[2];
  if (co==0) {
      norm=(float)(p1->zp.x-p0->zp.x)*(float)(p2->zp.y-p0->zp.y)-
        (float)(p2->zp.x-p0->zp.x)*(float)(p1->zp.y-p0->zp.y);
      if (norm == 0) return;
      front = norm < 0.0;
      front = front ^ c->current_front_face;
      if (c->cull_face_enabled) {
        if (c->current_cull_face == GL_BACK) {
          if (front == 0) return;
          c->draw_triangle_front(c,p0,p1,p2);
        } else if (c->current_cull_face == GL_FRONT) {
          if (front != 0) return;
          c->draw_triangle_back(c,p0,p1,p2);
        } else {
          return;
        }
      } else {
        if (front) {
          c->draw_triangle_front(c,p0,p1,p2);
        } else {
          c->draw_triangle_back(c,p0,p1,p2);
        }
      }
  } else {
    c_and=cc[0] & cc[1] & cc[2];
    if (c_and==0) {
      gl_draw_triangle_clip(c,p0,p1,p2,0);
    }
  }
}

static void snake_key(int key) {
  if (snake_game_over) {
    snake_init();
    return;
  }
  int new_dir = snake_dir;
  if (key == 0x100 || key == 'w' || key == 'W')
    new_dir = 0; 
  else if (key == 0x103 || key == 'd' || key == 'D')
    new_dir = 1; 
  else if (key == 0x101 || key == 's' || key == 'S')
    new_dir = 2; 
  else if (key == 0x102 || key == 'a' || key == 'A')
    new_dir = 3; 
  if ((snake_dir == 0 && new_dir == 2) || (snake_dir == 2 && new_dir == 0) ||
      (snake_dir == 1 && new_dir == 3) || (snake_dir == 3 && new_dir == 1)) {
    return;
  }
  snake_dir = new_dir;
  snake_move(); 
}

