				- inout[inoutPos + 5 * 3];
		tc0 = inout[inoutPos + 0 * 3] * win[Encoder.SHORT_TYPE][2]
				- inout[inoutPos + 3 * 3];
		tc1 = ts0 + tc0;
		tc2 = ts0 - tc0;
		ts0 = inout[inoutPos + 5 * 3] * win[Encoder.SHORT_TYPE][0]
				+ inout[inoutPos + 2 * 3];
		tc0 = inout[inoutPos + 3 * 3] * win[Encoder.SHORT_TYPE][2]
				+ inout[inoutPos + 0 * 3];
		ts1 = ts0 + tc0;
		ts2 = -ts0 + tc0;
