int levenshtein(const char *s1, const char *s2)
{
    int len1 = strlen(s1);
    int len2 = strlen(s2);
    if (abs(len1 - len2) > 3)
    {
        return 999;
    }
    int *matrix = malloc((size_t)(len1 + 1) * (size_t)(len2 + 1) * sizeof(int));
    if (!matrix)
    {
        return 999;
    }
#define MATRIX(i, j) matrix[(i) * (len2 + 1) + (j)]
    for (int i = 0; i <= len1; i++)
    {
        MATRIX(i, 0) = i;
    }
    for (int j = 0; j <= len2; j++)
    {
        MATRIX(0, j) = j;
    }
    for (int i = 1; i <= len1; i++)
    {
        for (int j = 1; j <= len2; j++)
        {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            int del = MATRIX(i - 1, j) + 1;
            int ins = MATRIX(i, j - 1) + 1;
            int sub = MATRIX(i - 1, j - 1) + cost;
            MATRIX(i, j) = (del < ins) ? del : ins;
            if (sub < MATRIX(i, j))
            {
                MATRIX(i, j) = sub;
            }
        }
    }
    int result = MATRIX(len1, len2);
    zfree(matrix);
    return result;
}

int
lwip_fcntl(int s, int cmd, int val)
{
  struct lwip_sock *sock = get_socket(s);
  int ret = -1;
  int op_mode = 0;
  if (!sock) {
    return -1;
  }
  switch (cmd) {
    case F_GETFL:
      ret = netconn_is_nonblocking(sock->conn) ? O_NONBLOCK : 0;
      set_errno(0);
      if (NETCONNTYPE_GROUP(netconn_type(sock->conn)) != NETCONN_TCP) {
#if LWIP_TCPIP_CORE_LOCKING
        LOCK_TCPIP_CORE();
#else
        SYS_ARCH_DECL_PROTECT(lev);
        SYS_ARCH_PROTECT(lev);
#endif
#if LWIP_TCP
        if (sock->conn->pcb.tcp) {
          if (!(sock->conn->pcb.tcp->flags & TF_RXCLOSED)) {
            op_mode |= O_RDONLY;
          }
          if (!(sock->conn->pcb.tcp->flags & TF_FIN)) {
            op_mode |= O_WRONLY;
          }
        }
#endif
#if LWIP_TCPIP_CORE_LOCKING
        UNLOCK_TCPIP_CORE();
#else
        SYS_ARCH_UNPROTECT(lev);
#endif
      } else {
        op_mode |= O_RDWR;
      }
      ret |= (op_mode == (O_RDONLY | O_WRONLY)) ? O_RDWR : op_mode;
      break;
    case F_SETFL:
      val &= ~(O_RDONLY | O_WRONLY | O_RDWR);
      if ((val & ~O_NONBLOCK) == 0) {
        netconn_set_nonblocking(sock->conn, val & O_NONBLOCK);
        ret = 0;
        set_errno(0);
      } else {
        set_errno(ENOSYS); 
      }
      break;
    default:
      LWIP_DEBUGF(SOCKETS_DEBUG, ("lwip_fcntl(%d, UNIMPL: %d, %d)\n", s, cmd, val));
      set_errno(ENOSYS); 
      break;
  }
  done_socket(sock);
  return ret;
}

function resolvePluginRoot() {
  const envRoot = process.env.CLAUDE_PLUGIN_ROOT || '';
  if (hasRunnerRoot(envRoot)) {
    return path.resolve(envRoot.trim());
  }
  const home = require('os').homedir();
  const claudeDir = path.join(home, '.claude');
  if (hasRunnerRoot(claudeDir)) {
    return claudeDir;
  }
  const knownPaths = KNOWN_PLUGIN_PATHS.map((segments) =>
    path.join(claudeDir, 'plugins', ...segments)
  );
  for (const candidate of knownPaths) {
    if (hasRunnerRoot(candidate)) {
      return candidate;
    }
  }
  try {
    for (const slug of CACHE_PLUGIN_SLUGS) {
      const cacheBase = path.join(claudeDir, 'plugins', 'cache', slug);
      for (const org of fs.readdirSync(cacheBase, { withFileTypes: true })) {
        if (!org.isDirectory()) continue;
        for (const version of fs.readdirSync(path.join(cacheBase, org.name), { withFileTypes: true })) {
          if (!version.isDirectory()) continue;
          const candidate = path.join(cacheBase, org.name, version.name);
          if (hasRunnerRoot(candidate)) {
            return candidate;
          }
        }
      }
    }
  } catch {
  }
  return claudeDir;
}

