bool apuUpdate()
{
#ifdef __LIBRETRO__
	audioUpdate();
#else
	int updateRes = audioUpdate();
	if(updateRes != 0)
	{
		emuSkipFrame = false;
		apu.waitForRefill = false;
		return false;
	}
	if(apu.waitForRefill && updateRes < 2)
	{
		apu.waitForRefill = false;
		emuSkipFrame = false;
	}
	else if(!apu.waitForRefill && updateRes > 2)
	{
		emuSkipFrame = true;
		apu.waitForRefill = true;
	}
#endif
	apu.curBufPos = 0;
	return true;
}

