CJSON_PUBLIC(void) cJSON_Minify(char *json)
{
    char *into = json;
    if (json == NULL)
    {
        return;
    }
    while (json[0] != '\0')
    {
        switch (json[0])
        {
        case ' ':
        case '\t':
        case '\r':
        case '\n':
            json++;
            break;
        case '/':
            if (json[1] == '/')
            {
                skip_oneline_comment(&json);
            }
            else if (json[1] == '*')
            {
                skip_multiline_comment(&json);
            }
            else
            {
                json++;
            }
            break;
        case '\"':
            minify_string(&json, (char **)&into);
            break;
        default:
            into[0] = json[0];
            json++;
            into++;
        }
    }
    *into = '\0';
}

