static void zipfileStep(sqlite3_context *pCtx, int nVal, sqlite3_value **apVal){
  ZipfileCtx *p;                  
  ZipfileEntry e;                 
  sqlite3_value *pName = 0;
  sqlite3_value *pMode = 0;
  sqlite3_value *pMtime = 0;
  sqlite3_value *pData = 0;
  sqlite3_value *pMethod = 0;
  int bIsDir = 0;
  u32 mode;
  int rc = SQLITE_OK;
  char *zErr = 0;
  int iMethod = -1;               
  const u8 *aData = 0;            
  int nData = 0;                  
  int szUncompressed = 0;         
  u8 *aFree = 0;                  
  u32 iCrc32 = 0;                 
  char *zName = 0;                
  int nName = 0;                  
  char *zFree = 0;                
  int nByte;
  memset(&e, 0, sizeof(e));
  p = (ZipfileCtx*)sqlite3_aggregate_context(pCtx, sizeof(ZipfileCtx));
  if( p==0 ) return;
  if( nVal!=2 && nVal!=4 && nVal!=5 ){
    zErr = sqlite3_mprintf("wrong number of arguments to function zipfile()");
    rc = SQLITE_ERROR;
    goto zipfile_step_out;
  }
  pName = apVal[0];
  if( nVal==2 ){
    pData = apVal[1];
  }else{
    pMode = apVal[1];
    pMtime = apVal[2];
    pData = apVal[3];
    if( nVal==5 ){
      pMethod = apVal[4];
    }
  }
  zName = (char*)sqlite3_value_text(pName);
  nName = sqlite3_value_bytes(pName);
  if( zName==0 ){
    zErr = sqlite3_mprintf("first argument to zipfile() must be non-NULL");
    rc = SQLITE_ERROR;
    goto zipfile_step_out;
  }
  if( nName>ZIPFILE_MX_NAME ){
    zErr = sqlite3_mprintf(
               "filename argument to zipfile() too big; max: %d bytes",
               ZIPFILE_MX_NAME);
    rc = SQLITE_ERROR;
    goto zipfile_step_out;
  }
  if( pMethod && SQLITE_NULL!=sqlite3_value_type(pMethod) ){
    iMethod = (int)sqlite3_value_int64(pMethod);
    if( iMethod!=0 && iMethod!=8 ){
      zErr = sqlite3_mprintf("illegal method value: %d", iMethod);
      rc = SQLITE_ERROR;
      goto zipfile_step_out;
    }
  }
  if( sqlite3_value_type(pData)==SQLITE_NULL ){
    bIsDir = 1;
    iMethod = 0;
  }else{
    aData = sqlite3_value_blob(pData);
    szUncompressed = nData = sqlite3_value_bytes(pData);
    iCrc32 = crc32(0, aData, nData);
    if( iMethod<0 || iMethod==8 ){
      int nOut = 0;
      rc = zipfileDeflate(aData, nData, &aFree, &nOut, &zErr);
      if( rc!=SQLITE_OK ){
        goto zipfile_step_out;
      }
      if( iMethod==8 || nOut<nData ){
        aData = aFree;
        nData = nOut;
        iMethod = 8;
      }else{
        iMethod = 0;
      }
    }
  }
  rc = zipfileGetMode(pMode, bIsDir, &mode, &zErr);
  if( rc ) goto zipfile_step_out;
  e.mUnixTime = zipfileGetTime(pMtime);
  if( bIsDir==0 ){
    if( nName>0 && zName[nName-1]=='/' ){
      zErr = sqlite3_mprintf("non-directory name must not end with /");
      rc = SQLITE_ERROR;
      goto zipfile_step_out;
    }
  }else{
    if( nName==0 || zName[nName-1]!='/' ){
      zName = zFree = sqlite3_mprintf("%s/", zName);
      if( zName==0 ){
        rc = SQLITE_NOMEM;
        goto zipfile_step_out;
      }
      nName = (int)strlen(zName);
    }else{
      while( nName>1 && zName[nName-2]=='/' ) nName--;
    }
  }
  e.cds.iVersionMadeBy = ZIPFILE_NEWENTRY_MADEBY;
  e.cds.iVersionExtract = ZIPFILE_NEWENTRY_REQUIRED;
  e.cds.flags = ZIPFILE_NEWENTRY_FLAGS;
  e.cds.iCompression = (u16)iMethod;
  zipfileMtimeToDos(&e.cds, (u32)e.mUnixTime);
  e.cds.crc32 = iCrc32;
  e.cds.szCompressed = nData;
  e.cds.szUncompressed = szUncompressed;
  e.cds.iExternalAttr = (mode<<16);
  e.cds.iOffset = p->body.n;
  e.cds.nFile = (u16)nName;
  e.cds.zFile = zName;
  nByte = ZIPFILE_LFH_FIXED_SZ + e.cds.nFile + 9;
  if( (rc = zipfileBufferGrow(&p->body, nByte)) ) goto zipfile_step_out;
  p->body.n += zipfileSerializeLFH(&e, &p->body.a[p->body.n]);
  if( nData>0 ){
    if( (rc = zipfileBufferGrow(&p->body, nData)) ) goto zipfile_step_out;
    memcpy(&p->body.a[p->body.n], aData, nData);
    p->body.n += nData;
  }
  nByte = ZIPFILE_CDS_FIXED_SZ + e.cds.nFile + 9;
  if( (rc = zipfileBufferGrow(&p->cds, nByte)) ) goto zipfile_step_out;
  p->cds.n += zipfileSerializeCDS(&e, &p->cds.a[p->cds.n]);
  p->nEntry++;
 zipfile_step_out:
  sqlite3_free(aFree);
  sqlite3_free(zFree);
  if( rc ){
    if( zErr ){
      sqlite3_result_error(pCtx, zErr, -1);
    }else{
      sqlite3_result_error_code(pCtx, rc);
    }
  }
  sqlite3_free(zErr);
}

static unsigned int strHash(const char *z){
  unsigned int h = 0;
  while( z[0] ){     
#ifdef SQLITE_EBCDIC
    h += 0xbf & (unsigned char)*(z++);
#else
    h += 0xdf & (unsigned char)*(z++);
#endif
    h *= 0x9e3779b1;
  }
  return h;
}

static int lua_knob_off(lua_State *L)
{
    knob_handle_t   handle    = lua_knob_check_handle(L, 1);
    const char     *event_str = luaL_optstring(L, 2, NULL);
    knob_lua_reg_t *reg       = knob_find_reg(handle);
    if (!reg) {
        lua_pushnil(L);
        lua_pushstring(L, "invalid or closed knob handle");
        return 2;
    }
    if (event_str) {
        knob_event_t ev = knob_event_from_str(event_str);
        if (ev != KNOB_EVENT_MAX) {
            lua_pushnil(L);
            lua_pushfstring(L, "unknown event '%s'", event_str);
            return 2;
        }
        if (reg->lua_refs[ev] != LUA_NOREF) {
            luaL_unref(L, LUA_REGISTRYINDEX, reg->lua_refs[ev]);
            reg->lua_refs[ev] = LUA_NOREF;
        }
        if (reg->cbs_registered[ev]) {
            esp_err_t err = iot_knob_unregister_cb(handle, ev);
            if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
                lua_pushnil(L);
                lua_pushfstring(L, "unregister_cb failed for event '%s': %s",
                                event_str, esp_err_to_name(err));
                return 2;
            }
            reg->cbs_registered[ev] = false;
        }
    } else {
        for (int i = 0; i < KNOB_EVENT_MAX; i++) {
            if (reg->lua_refs[i] != LUA_NOREF) {
                luaL_unref(L, LUA_REGISTRYINDEX, reg->lua_refs[i]);
                reg->lua_refs[i] = LUA_NOREF;
            }
            if (reg->cbs_registered[i]) {
                esp_err_t err = iot_knob_unregister_cb(handle, (knob_event_t)i);
                if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
                    ESP_LOGW(TAG, "unregister_cb failed for event %s: %s",
                             knob_event_to_str((knob_event_t)i), esp_err_to_name(err));
                }
                reg->cbs_registered[i] = false;
            }
        }
    }
    lua_pushboolean(L, 1);
    return 1;
}

bool tagtinker_ir_transmit(const uint8_t* data, size_t len, uint16_t repeats_raw, uint8_t delay) {
    if(!ir_initialized) return false;
    if(!data || len == 0 || len > 255) return false;
    ir_stop_requested = false;
    uint32_t repeats = repeats_raw & 0x7FFF;
    for(uint32_t rep = 0; rep <= repeats; rep++) {
        if(ir_stop_requested) {
            carrier_off();
            return false;
        }
        FURI_CRITICAL_ENTER();
        send_frame_pp4(data, len);
        FURI_CRITICAL_EXIT();
        if(rep < repeats) {
            if(delay > 0) {
                uint32_t gap_cycles = (uint32_t)delay * 32000U; 
                delay_cycles(gap_cycles);
            }
            if((rep % 5U) == 4U) furi_delay_ms(1);
        }
    }
    return true;
}

function calc_interchannel_masking(gfp, ratio) {
    var gfc = gfp.internal_flags;
    if (gfc.channels_out > 1) {
        for (var sb = 0; sb < Encoder.SBMAX_l; sb++) {
            var l = gfc.thm[0].l[sb];
            var r = gfc.thm[1].l[sb];
            gfc.thm[0].l[sb] += r * ratio;
            gfc.thm[1].l[sb] += l * ratio;
        }
        for (var sb = 0; sb < Encoder.SBMAX_s; sb++) {
            for (var sblock = 0; sblock < 3; sblock++) {
                var l = gfc.thm[0].s[sb][sblock];
                var r = gfc.thm[1].s[sb][sblock];
                gfc.thm[0].s[sb][sblock] += r * ratio;
                gfc.thm[1].s[sb][sblock] += l * ratio;
            }
        }
    }
}

static void ws2812b_set_byte(struct ws2812b_priv *priv, size_t offset, u8 val)
{
	const u8 h3b[] = { 0x92, 0x93, 0x9a, 0x9b, 0xd2, 0xd3, 0xda, 0xdb };
	const u8 m2b[] = { 0x49, 0x4d, 0x69, 0x6d };
	const u8 l3b[] = { 0x24, 0x26, 0x34, 0x36, 0xa4, 0xa6, 0xb4, 0xb6 };
	u8 *p = priv->data_buf + WS2812B_RESET_LEN + (offset * WS2812B_BYTES_PER_COLOR);
	p[0] = h3b[val >> 5]; 
	p[1] = m2b[(val >> 3) & 0x3]; 
	p[2] = l3b[val & 0x7]; 
}

