function formatSSE(data, sourceFormat) {
  if (data === null || data === undefined) return "data: null\n\n";
  if (data && data.done) return "data: [DONE]\n\n";
  if (data && data.event && data.data) {
    const cleanedEventData = cleanUsagePayload(data.data);
    return `event: ${data.event}\ndata: ${JSON.stringify(cleanedEventData)}\n\n`;
  }
  data = cleanUsagePayload(data);
  if (sourceFormat === FORMATS.CLAUDE && data && data.type) {
    return `event: ${data.type}\ndata: ${JSON.stringify(data)}\n\n`;
  }
  return `data: ${JSON.stringify(data)}\n\n`;
}

function deepMerge(target, source) {
  if (!isPlainObject(target) || !isPlainObject(source)) {
    return source !== undefined ? source : target;
  }
  const result = { ...target };
  for (const [key, value] of Object.entries(source)) {
    if (key.endsWith('+append')) {
      const baseKey = key.slice(0, -7); 
      if (Array.isArray(value)) {
        const existing = result[baseKey];
        result[baseKey] = Array.isArray(existing)
          ? [...existing, ...value]
          : value;
      }
      continue;
    }
    if (value === null) {
      delete result[key];
      continue;
    }
    if (isPlainObject(value) || isPlainObject(result[key])) {
      result[key] = deepMerge(result[key], value);
      continue;
    }
    result[key] = value;
  }
  return result;
}

