async function getProjectForAccount(account, token, projectCache, onSave = null) {
    const cached = projectCache.get(account.email);
    if (cached) {
        return cached;
    }
    const parts = account.refreshToken ? parseRefreshParts(account.refreshToken) : { refreshToken: null, projectId: undefined, managedProjectId: undefined };
    if (parts.managedProjectId) {
        projectCache.set(account.email, parts.managedProjectId);
        if (!account.subscription || account.subscription.tier === 'unknown') {
            await fetchAndSaveSubscription(token, account, onSave);
        }
        return parts.managedProjectId;
    }
    if (account.projectId) {
        projectCache.set(account.email, account.projectId);
        if (!account.subscription || account.subscription.tier === 'unknown') {
            await fetchAndSaveSubscription(token, account, onSave);
        }
        return account.projectId;
    }
    const { project, subscription } = await discoverProject(token, parts.projectId);
    if (project && project !== DEFAULT_PROJECT_ID) {
        let needsSave = false;
        if (account.refreshToken) {
            account.refreshToken = formatRefreshParts({
                refreshToken: parts.refreshToken,
                projectId: parts.projectId,
                managedProjectId: project,
            });
            needsSave = true;
        } else if (account.source === 'database' || account.source === 'manual') {
            account.projectId = project;
            needsSave = true;
        }
        if (subscription) {
            account.subscription = subscription;
            needsSave = true;
        }
        if (needsSave && onSave) {
            try {
                await onSave();
            } catch (e) {
                logger.warn(`[AccountManager] Failed to save updated project: ${e.message}`);
            }
        }
    } else if (subscription) {
        account.subscription = subscription;
        if (onSave) {
            try {
                await onSave();
            } catch (e) {
                logger.warn(`[AccountManager] Failed to save subscription: ${e.message}`);
            }
        }
    }
    projectCache.set(account.email, project);
    return project;
}

static void desktop_commit_rename(void) {
  if (!rename_active || rename_icon_idx < 0 ||
      rename_icon_idx >= desktop_icon_count)
    return;
  desktop_icon_t *icon = &desktop_icons[rename_icon_idx];
  if (rename_buffer[0] && str_cmp(icon->name, rename_buffer) != 0) {
    char new_path[256];
    str_copy(new_path, DESKTOP_PATH, 256);
    int len = 0;
    while (new_path[len])
      len++;
    new_path[len++] = '/';
    str_copy(new_path + len, rename_buffer, 256 - len);
    extern int vfs_rename(const char *oldpath, const char *newpath);
    int ret = vfs_rename(icon->path, new_path);
    if (ret == 0) {
      str_copy(icon->name, rename_buffer, 64);
      str_copy(icon->path, new_path, 256);
      printk(KERN_INFO "DESKTOP: Renamed to %s\n", rename_buffer);
    } else {
      printk(KERN_ERR "DESKTOP: Rename failed: %d\n", ret);
    }
  }
  desktop_mark_dirty(icon->x - 10, icon->y + DESKTOP_ICON_SIZE,
                     DESKTOP_ICON_SIZE + 60, DESKTOP_LABEL_HEIGHT + 10);
  rename_active = 0;
  rename_icon_idx = -1;
  rename_buffer[0] = '\0';
  rename_cursor = 0;
}

function formatRelativeTime(timestamp) {
  if (!timestamp) return 'Never';
  const diff = Date.now() - new Date(timestamp).getTime();
  const minutes = Math.floor(diff / 60000);
  const hours = Math.floor(diff / 3600000);
  const days = Math.floor(diff / 86400000);
  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  return `${days}d ago`;
}

