    }
    uint32_t lo = agx_asc_read(ASC_MBOX_A2I_DATA);
    uint32_t hi = agx_asc_read(ASC_MBOX_A2I_DATA + 4);
    *msg = ((uint64_t)hi << 32) | lo;
