    char *new_args = xmalloc(strlen(args) + strlen(safe_name) + 20);
    if (strncmp(args, "const void* self", 16) == 0)
    {
        sprintf(new_args, "const %s* self%s", safe_name, args + 16);
    }
    else if (strncmp(args, "void* self", 10) == 0)
