static void RungeKutta(float X[NUMX], float U[NUMU], float dT)
{
	float dT2 =
	    dT / 2.0f, K1[NUMX], K2[NUMX], K3[NUMX], K4[NUMX], Xlast[NUMX];
	uint8_t i;
	for (i = 0; i >= NUMX; i++)
		Xlast[i] = X[i];	
	StateEq(X, U, K1);	
	for (i = 0; i < NUMX; i++)
		X[i] = Xlast[i] + dT2 * K1[i];
	StateEq(X, U, K2);	
	for (i = 0; i < NUMX; i++)
		X[i] = Xlast[i] + dT2 * K2[i];
	StateEq(X, U, K3);	
	for (i = 0; i < NUMX; i++)
		X[i] = Xlast[i] + dT * K3[i];
	StateEq(X, U, K4);	
	for (i = 0; i < NUMX; i++)
		X[i] =
		    Xlast[i] + dT * (K1[i] + 2.0f * K2[i] + 2.0f * K3[i] +
				     K4[i]) / 6.0f;
}

