function quantize_xrpow(xp, pi, istep, codInfo, prevNoise) {
    var sfb;
    var sfbmax;
    var j = 0;
    var prev_data_use;
    var accumulate = 0;
    var accumulate01 = 0;
    var xpPos = 0;
    var iData = pi;
    var iDataPos = 0;
    var acc_iData = iData;
    var acc_iDataPos = 0;
    var acc_xp = xp;
    var acc_xpPos = 0;
    prev_data_use = (prevNoise != null && (codInfo.global_gain != prevNoise.global_gain));
    if (codInfo.block_type == Encoder.SHORT_TYPE)
        sfbmax = 38;
    else
        sfbmax = 21;
    for (sfb = 0; sfb <= sfbmax; sfb++) {
        var step = -1;
        if (prev_data_use || codInfo.block_type == Encoder.NORM_TYPE) {
            step = codInfo.global_gain
                - ((codInfo.scalefac[sfb] + (codInfo.preflag != 0 ? qupvt.pretab[sfb]
                    : 0)) << (codInfo.scalefac_scale + 1))
                - codInfo.subblock_gain[codInfo.window[sfb]] * 8;
        }
        if (prev_data_use && (prevNoise.step[sfb] == step)) {
            if (accumulate != 0) {
                quantize_lines_xrpow(accumulate, istep, acc_xp, acc_xpPos,
                    acc_iData, acc_iDataPos);
                accumulate = 0;
            }
            if (accumulate01 != 0) {
                quantize_lines_xrpow_01(accumulate01, istep, acc_xp,
                    acc_xpPos, acc_iData, acc_iDataPos);
                accumulate01 = 0;
            }
        } else { 
            var l = codInfo.width[sfb];
            if ((j + codInfo.width[sfb]) > codInfo.max_nonzero_coeff) {
                var usefullsize;
                usefullsize = codInfo.max_nonzero_coeff - j + 1;
                Arrays.fill(pi, codInfo.max_nonzero_coeff, 576, 0);
                l = usefullsize;
                if (l < 0) {
                    l = 0;
                }
                sfb = sfbmax + 1;
            }
            if (0 == accumulate && 0 == accumulate01) {
                acc_iData = iData;
                acc_iDataPos = iDataPos;
                acc_xp = xp;
                acc_xpPos = xpPos;
            }
            if (prevNoise != null && prevNoise.sfb_count1 > 0
                && sfb >= prevNoise.sfb_count1
                && prevNoise.step[sfb] > 0
                && step >= prevNoise.step[sfb]) {
                if (accumulate != 0) {
                    quantize_lines_xrpow(accumulate, istep, acc_xp,
                        acc_xpPos, acc_iData, acc_iDataPos);
                    accumulate = 0;
                    acc_iData = iData;
                    acc_iDataPos = iDataPos;
                    acc_xp = xp;
                    acc_xpPos = xpPos;
                }
                accumulate01 += l;
            } else {
                if (accumulate01 != 0) {
                    quantize_lines_xrpow_01(accumulate01, istep, acc_xp,
                        acc_xpPos, acc_iData, acc_iDataPos);
                    accumulate01 = 0;
                    acc_iData = iData;
                    acc_iDataPos = iDataPos;
                    acc_xp = xp;
                    acc_xpPos = xpPos;
                }
                accumulate += l;
            }
            if (l <= 0) {
                if (accumulate01 != 0) {
                    quantize_lines_xrpow_01(accumulate01, istep, acc_xp,
                        acc_xpPos, acc_iData, acc_iDataPos);
                    accumulate01 = 0;
                }
                if (accumulate != 0) {
                    quantize_lines_xrpow(accumulate, istep, acc_xp,
                        acc_xpPos, acc_iData, acc_iDataPos);
                    accumulate = 0;
                }
                break;
            }
        }
        if (sfb <= sfbmax) {
            iDataPos += codInfo.width[sfb];
            xpPos += codInfo.width[sfb];
            j += codInfo.width[sfb];
        }
    }
    if (accumulate != 0) { 
        quantize_lines_xrpow(accumulate, istep, acc_xp, acc_xpPos,
            acc_iData, acc_iDataPos);
        accumulate = 0;
    }
    if (accumulate01 != 0) { 
        quantize_lines_xrpow_01(accumulate01, istep, acc_xp, acc_xpPos,
            acc_iData, acc_iDataPos);
        accumulate01 = 0;
    }
}

def _monitor(self, thread):


        logger.debug("Launching Monitor")
        logger.info("===================================================")
        logger.info("  Starting")
        if self._args.preview:
            logger.info("  Using live preview")
        if sys.stdout.isatty():
            logger.info("  Press '%s' to save and quit",
                        "Stop" if self._args.redirect_gui or self._args.colab else "ENTER")
        if not self._args.redirect_gui and not self._args.colab and sys.stdout.isatty():
            logger.info("  Press 'S' to save model weights immediately")
        logger.info("===================================================")

        keypress = KBHit(is_gui=self._args.redirect_gui)
        window_created = True
        err = False
        while True:
            try:
                if self._args.preview:
                    with self._lock:
                        for name, image in self._preview_buffer.items():
                            if not window_created:
                                self._create_resizable_window(name, image.shape)
                            cv2.imshow(name, image)  # pylint: disable=no-member
                        if not window_created:
                            window_created = bool(self._preview_buffer)
                    cv_key = cv2.waitKey(1000)  # pylint: disable=no-member
                else:
                    cv_key = None

                if thread.has_error:
                    logger.debug("Thread error detected")
                    err = True
                    break
                if self._stop:
                    logger.debug("Stop received")
                    break

                # Preview Monitor
                if not self._preview_monitor(cv_key):
                    break

                # Console Monitor
                if keypress.kbhit():
                    console_key = keypress.getch()
                    if console_key in ("\n", "\r"):
                        logger.debug("Exit requested")
                        break
                    if console_key in ("s", "S"):
                        logger.info("Save requested")
                        self._save_now = True

                # GUI Preview trigger update monitor
                self._process_gui_triggers()

                sleep(1)
            except KeyboardInterrupt:
                logger.debug("Keyboard Interrupt received")
                break
        keypress.set_normal_term()
        logger.debug("Closed Monitor")
        return err

function parseBorderRadius(raw) {
  if (!raw || raw === '0px') return [];
  const parts = raw.split('/')[0].trim().split(/\s+/);
  const values = [];
  for (const p of parts) {
    const v = parseCSSValue(p);
    if (v && v.value > 0) values.push(Math.round(v.value));
  }
  return values;
}

