        if (/^-?\d+(\.\d+)?$/.test(s)) {
          const n = Number(s)
          if (!Number.isFinite(n)) return null
          const msNum = Math.abs(n) < 1e10 ? n * 1000 : n
          const dn = new Date(msNum)
          const tn = dn.getTime()
