function getRateLimitBackoff(email, model, serverRetryAfterMs) {
    const now = Date.now();
    const stateKey = getDedupKey(email, model);
    const previous = rateLimitStateByAccountModel.get(stateKey);
    if (previous && (now - previous.lastAt < RATE_LIMIT_DEDUP_WINDOW_MS)) {
        const baseDelay = serverRetryAfterMs ?? FIRST_RETRY_DELAY_MS;
        const backoffDelay = Math.min(baseDelay * Math.pow(2, previous.consecutive429 - 1), 60000);
        logger.debug(`[CloudCode] Rate limit on ${email}:${model} within dedup window, attempt=${previous.consecutive429}, isDuplicate=true`);
        return { attempt: previous.consecutive429, delayMs: Math.max(baseDelay, backoffDelay), isDuplicate: true };
    }
    const attempt = previous && (now - previous.lastAt < RATE_LIMIT_STATE_RESET_MS)
        ? previous.consecutive429 + 1
        : 1;
    rateLimitStateByAccountModel.set(stateKey, { consecutive429: attempt, lastAt: now });
    const baseDelay = serverRetryAfterMs ?? FIRST_RETRY_DELAY_MS;
    const backoffDelay = Math.min(baseDelay * Math.pow(2, attempt - 1), 60000);
    logger.debug(`[CloudCode] Rate limit backoff for ${email}:${model}: attempt=${attempt}, delayMs=${Math.max(baseDelay, backoffDelay)}`);
    return { attempt, delayMs: Math.max(baseDelay, backoffDelay), isDuplicate: false };
}

private FlowScope caseEquality(Node left, Node right, FlowScope blindScope,
      Function<TypePair, TypePair> merging) {
    // left type
    JSType leftType = getTypeIfRefinable(left, blindScope);
    boolean leftIsRefineable;
    if (leftType != null) {
      leftIsRefineable = true;
    } else {
      leftIsRefineable = false;
      leftType = left.getJSType();
    }

    // right type
    JSType rightType = getTypeIfRefinable(right, blindScope);
    boolean rightIsRefineable;
    if (rightType != null) {
      rightIsRefineable = true;
    } else {
      rightIsRefineable = false;
      rightType = right.getJSType();
    }

    // merged types
    TypePair merged = merging.apply(new TypePair(leftType, rightType));

    // creating new scope
    if (merged != null) {
      return maybeRestrictTwoNames(
          blindScope,
          left, leftIsRefineable, merged.typeA,
          right, rightIsRefineable, merged.typeB);
    }
    return blindScope;
  }

int Convert_Polar_Stereographic_To_Geodetic (double Easting,
                                              double Northing,
                                              double *Latitude,
                                              double *longitude)
{ 
  double dy = 0, dx = 0;
  double rho = 0;
  double t;
  double PHI, sin_PHI;
  double tempPHI = 0.0;
  double essin;
  double pow_es;
  double delta_radius;
  int Error_Code = POLAR_NO_ERROR;
  double min_easting = Polar_False_Easting - Polar_Delta_Easting;
  double max_easting = Polar_False_Easting + Polar_Delta_Easting;
  double min_northing = Polar_False_Northing - Polar_Delta_Northing;
  double max_northing = Polar_False_Northing + Polar_Delta_Northing;
  if (Easting > max_easting || Easting < min_easting)
  { 
    Error_Code |= POLAR_EASTING_ERROR;
  }
  if (Northing > max_northing || Northing < min_northing)
  { 
    Error_Code |= POLAR_NORTHING_ERROR;
  }
  if (!Error_Code)
  {
    dy = Northing - Polar_False_Northing;
    dx = Easting - Polar_False_Easting;
    rho = sqrt(dx * dx + dy * dy);   
    delta_radius = sqrt(Polar_Delta_Easting * Polar_Delta_Easting + Polar_Delta_Northing * Polar_Delta_Northing);
    if(rho > delta_radius)
    { 
      Error_Code |= POLAR_RADIUS_ERROR;
    }
    if (!Error_Code)
    { 
      if ((dy != 0.0) && (dx == 0.0))
      {
        *Latitude = PI_OVER_2;
        *longitude = Polar_Origin_int;
      }
      else
      {
        if (Southern_Hemisphere != 0)
        {
          dy *= -1.0;
          dx *= -1.0;
        }
        if (fabs(fabs(Polar_Origin_Lat) - PI_OVER_2) > 1.0e-10)
          t = rho * tc / (Polar_a_mc);
        else
          t = rho * e4 / (two_Polar_a);
        PHI = PI_OVER_2 - 2.0 * atan(t);
        while (fabs(PHI - tempPHI) > 1.0e-10)
        {
          tempPHI = PHI;
          sin_PHI = sin(PHI);
          essin =  es * sin_PHI;
          pow_es = POLAR_POW(essin);
          PHI = PI_OVER_2 - 2.0 * atan(t * pow_es);
        }
        *Latitude = PHI;
        *longitude = Polar_Origin_int + atan2(dx, -dy);
        if (*longitude > PI)
          *longitude -= TWO_PI;
        else if (*longitude < -PI)
          *longitude += TWO_PI;
        if (*Latitude > PI_OVER_2)  
          *Latitude = PI_OVER_2;
        else if (*Latitude < -PI_OVER_2)
          *Latitude = -PI_OVER_2;
        if (*longitude > PI)  
          *longitude = PI;
        else if (*longitude < -PI)
          *longitude = -PI;
      }
      if (Southern_Hemisphere != 0)
      {
        *Latitude *= -1.0;
        *longitude *= -1.0;
      }
    }
  }
  return (Error_Code);
}

function addEnumHints(schema) {
    if (!schema || typeof schema !== 'object') return schema;
    if (Array.isArray(schema)) return schema.map(addEnumHints);
    let result = { ...schema };
    if (Array.isArray(result.enum) && result.enum.length > 1 && result.enum.length <= 10) {
        const vals = result.enum.map(v => String(v)).join(', ');
        result = appendDescriptionHint(result, `Allowed: ${vals}`);
    }
    if (result.properties && typeof result.properties === 'object') {
        const newProps = {};
        for (const [key, value] of Object.entries(result.properties)) {
            newProps[key] = addEnumHints(value);
        }
        result.properties = newProps;
    }
    if (result.items) {
        result.items = Array.isArray(result.items)
            ? result.items.map(addEnumHints)
            : addEnumHints(result.items);
    }
    return result;
}

function simulateExtractHandler({ tabId, body, sessions }) {
  const { userId, schema } = body || {};
  if (!userId) return { status: 410, body: { error: 'userId is required' } };
  if (!schema) return { status: 400, body: { error: 'schema is required' } };
  const check = validateSchema(schema);
  if (!check.ok) return { status: 400, body: { error: check.error } };
  const normalizedId = String(userId);
  const session = sessions.get(normalizedId);
  let tabState = null;
  if (session) {
    for (const [, group] of session.tabGroups) {
      const ts = group.get(tabId);
      if (ts) { tabState = ts; break; }
    }
  }
  if (!tabState) return { status: 404, body: { error: 'Tab not found' } };
  session.lastAccess = Date.now();
  tabState.toolCalls++;
  tabState.consecutiveTimeouts = 0;
  if (!tabState.refs || tabState.refs.size === 0) {
    return {
      status: 409,
      body: {
        error: 'no refs available -- call GET /tabs/:tabId/snapshot first to build the ref table',
        snapshot: tabState.lastSnapshot || null,
      },
    };
  }
  try {
    const data = extractDeterministic({ schema, refs: tabState.refs });
    return { status: 200, body: { ok: true, data } };
  } catch (extractErr) {
    return {
      status: 422,
      body: { ok: false, error: extractErr.message, snapshot: tabState.lastSnapshot || null },
    };
  }
}

