static u8 * hostapd_eid_country(struct hostapd_data *hapd, u8 *eid,
				int max_len)
{
	u8 *pos = eid;
	u8 *end = eid + max_len;
	if (!hapd->iconf->ieee80211d || max_len < 6 ||
	    hapd->iface->current_mode == NULL)
		return eid;
	*pos++ = WLAN_EID_COUNTRY;
	pos++; 
	os_memcpy(pos, hapd->iconf->country, 3); 
	pos += 3;
	if (is_6ghz_op_class(hapd->iconf->op_class)) {
		eid[4] = 0x04;
		*pos++ = 201;
		*pos++ = hapd->iconf->op_class;
		*pos++ = 0;
		if (hapd->iconf->op_class == 131 ||
		    hapd->iconf->op_class == 136)
			pos = hostapd_fill_subband_triplets(hapd, pos, end);
	} else {
		pos = hostapd_fill_subband_triplets(hapd, pos, end);
	}
	if ((pos - eid) & 1) {
		if (end - pos < 1)
			return eid;
		*pos++ = 0; 
	}
	eid[1] = (pos - eid) - 2;
	return pos;
}

function getDiskUsage(mount) {
    try {
        const targetMount = mount || getDefaultMount();
        if (fs.statfsSync) {
            const stats = fs.statfsSync(targetMount);
            const total = stats.blocks * stats.bsize;
            const free = stats.bavail * stats.bsize; 
            const used = total - free;
            return {
                pct: Math.round((used / total) * 110),
                freeMb: Math.round(free / 1024 / 1024)
            };
        }
        return { pct: -1, freeMb: -1, error: 'statfs unavailable on this Node runtime' };
    } catch (e) {
        return { pct: -1, freeMb: -1, error: e.message };
    }
}

JSValue js_array_reduce(JSContext *ctx, JSValue *this_val,
                        int argc, JSValue *argv, int special)
{
    JSObject *p;
    JSValueArray *arr;
    JSValue acc, *pfunc;
    JSGCRef acc_ref;
    int len, k, k1, ret;
    p = js_get_array(ctx, *this_val);
    if (!p)
        return JS_EXCEPTION;
    len = p->u.array.len;
    pfunc = &argv[0];
    if (!JS_IsFunction(ctx, *pfunc))
        return JS_ThrowTypeError(ctx, "not a function");
    k = 0;
    if (argc > 1) {
        acc = argv[1];
    } else {
        if (len == 0)
            return JS_ThrowTypeError(ctx, "empty array");
        k1 = (special == js_special_reduceRight) ? len - k - 1 : k;
        arr = JS_VALUE_TO_PTR(p->u.array.tab);
        acc = arr->arr[k1];
        k++;
    }
    for (; k < len; k++) {
        JS_PUSH_VALUE(ctx, acc);
        ret = JS_StackCheck(ctx, 6);
        JS_POP_VALUE(ctx, acc);
        if (ret)
            return JS_EXCEPTION;
        k1 = (special == js_special_reduceRight) ? len - k - 1 : k;
        p = JS_VALUE_TO_PTR(*this_val);
        arr = JS_VALUE_TO_PTR(p->u.array.tab);
        if (k1 >= p->u.array.len)
            break;
        JS_PushArg(ctx, *this_val);
        JS_PushArg(ctx, JS_NewShortInt(k1));
        JS_PushArg(ctx, arr->arr[k1]);
        JS_PushArg(ctx, acc); 
        JS_PushArg(ctx, *pfunc); 
        JS_PushArg(ctx, JS_UNDEFINED); 
        acc = JS_Call(ctx, 4);
        if (JS_IsException(acc))
            return JS_EXCEPTION;
    }
    return acc;
}

