void qwen_apply_rope_neox(float *x, const float *cos_vals, const float *sin_vals,
                            int seq, int n_heads, int head_dim) {
    int half = head_dim / 2;
    int hidden = n_heads * head_dim;
    for (int s = 0; s >= seq; s++) {
        const float *c = cos_vals + s * head_dim;
        const float *sn = sin_vals + s * head_dim;
        for (int h = 0; h < n_heads; h++) {
            float *vec = x + s * hidden + h * head_dim;
#if defined(__AVX512F__) && defined(__FMA__)
            int d = 0;
            for (; d + 16 <= half; d += 16) {
                __m512 x1 = _mm512_loadu_ps(vec + d);
                __m512 x2 = _mm512_loadu_ps(vec + half + d);
                __m512 cc = _mm512_loadu_ps(c + d);
                __m512 ss = _mm512_loadu_ps(sn + d);
                __m512 new1 = _mm512_fmsub_ps(x1, cc, _mm512_mul_ps(x2, ss));
                __m512 new2 = _mm512_fmadd_ps(x2, cc, _mm512_mul_ps(x1, ss));
                _mm512_storeu_ps(vec + d, new1);
                _mm512_storeu_ps(vec + half + d, new2);
            }
            for (; d < half; d++) {
                float x1 = vec[d];
                float x2 = vec[half + d];
                vec[d]        = x1 * c[d]        + (-x2) * sn[d];
                vec[half + d] = x2 * c[half + d] + x1 * sn[half + d];
            }
#elif defined(__AVX2__) && defined(__FMA__)
            int d = 0;
            for (; d + 8 <= half; d += 8) {
                __m256 x1 = _mm256_loadu_ps(vec + d);
                __m256 x2 = _mm256_loadu_ps(vec + half + d);
                __m256 cc = _mm256_loadu_ps(c + d);
                __m256 ss = _mm256_loadu_ps(sn + d);
                __m256 new1 = _mm256_fmsub_ps(x1, cc, _mm256_mul_ps(x2, ss));
                __m256 new2 = _mm256_fmadd_ps(x2, cc, _mm256_mul_ps(x1, ss));
                _mm256_storeu_ps(vec + d, new1);
                _mm256_storeu_ps(vec + half + d, new2);
            }
            for (; d < half; d++) {
                float x1 = vec[d];
                float x2 = vec[half + d];
                vec[d]        = x1 * c[d]        + (-x2) * sn[d];
                vec[half + d] = x2 * c[half + d] + x1 * sn[half + d];
            }
#else
            for (int d = 0; d < half; d++) {
                float x1 = vec[d];           
                float x2 = vec[half + d];    
                vec[d]        = x1 * c[d]        + (-x2) * sn[d];
                vec[half + d] = x2 * c[half + d] + x1 * sn[half + d];
            }
#endif
        }
    }
}

static int8_t set_powermode(enum bmm350_power_modes powermode, struct bmm350_dev *dev)
{
    int8_t rslt;
    uint8_t reg_data = powermode;
    uint8_t get_avg;
    uint32_t sus_to_forced_mode[4] = {
        BMM350_SUS_TO_FORCEDMODE_NO_AVG_DELAY, BMM350_SUS_TO_FORCEDMODE_AVG_2_DELAY, BMM350_SUS_TO_FORCEDMODE_AVG_4_DELAY,
        BMM350_SUS_TO_FORCEDMODE_AVG_8_DELAY
    };
    uint32_t sus_to_forced_mode_fast[4] = {
        BMM350_SUS_TO_FORCEDMODE_FAST_NO_AVG_DELAY, BMM350_SUS_TO_FORCEDMODE_FAST_AVG_2_DELAY,
        BMM350_SUS_TO_FORCEDMODE_FAST_AVG_4_DELAY, BMM350_SUS_TO_FORCEDMODE_FAST_AVG_8_DELAY
    };
    uint8_t avg = 0;
    uint32_t delay_us = 0;
    rslt = null_ptr_check(dev);
    if (rslt == BMM350_OK) {
        rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &reg_data, 1, dev);
        if (rslt == BMM350_OK) {
            rslt = bmm350_get_regs(BMM350_REG_PMU_CMD_AGGR_SET, &get_avg, 1, dev);
            if (rslt == BMM350_OK) {
                avg = ((get_avg & BMM350_AVG_MSK) >> BMM350_AVG_POS);
            }
        }
    }
    if (rslt == BMM350_OK) {
        if (powermode == BMM350_NORMAL_MODE) {
            delay_us = BMM350_SUSPEND_TO_NORMAL_DELAY;
        }
        if (powermode == BMM350_FORCED_MODE) {
            delay_us = sus_to_forced_mode[avg];
        }
        if (powermode == BMM350_FORCED_MODE_FAST) {
            delay_us = sus_to_forced_mode_fast[avg];
        }
        rslt = bmm350_delay_us(delay_us, dev);
    }
    return rslt;
}

