static int validate_box_is_permutation(const uint8_t* box, size_t len) {
    uint8_t inv[32]; 
    size_t i;
    if(len > sizeof(inv)) {
        return AUT64_ERR_INVALID_KEY;
    }
    for(i = 0; i < len; i++) {
        inv[i] = 0xFF;
    }
    for(i = 0; i < len; i++) {
        const uint8_t v = box[i];
        if(v >= len) {
            return AUT64_ERR_INVALID_KEY;
        }
        if(inv[v] != 0xFF) {
            return AUT64_ERR_INVALID_KEY;
        }
        inv[v] = (uint8_t)i;
    }
    for(i = 0; i < len; i++) {
        if(inv[i] == 0xFF) {
            return AUT64_ERR_INVALID_KEY;
        }
    }
    return AUT64_OK;
}

