      case NETCONN_TCP:
        err = tcp_bind(msg->conn->pcb.tcp, API_EXPR_REF(msg->msg.bc.ipaddr), msg->msg.bc.port);
        break;
#endif 
      default:
        err = ERR_VAL;
        break;
    }
  } else {
    err = ERR_VAL;
