static int hda_init_ring_buffer(void) {
  if (dma_buffer)
    return 0; 
  void *raw_bdl = kmalloc(HDA_RING_NUM_ENTRIES * sizeof(hda_bdl_entry_t) + 128);
  if (!raw_bdl)
    return -1;
  bdl = (hda_bdl_entry_t *)(((uint64_t)raw_bdl + 127) & ~127ULL);
  void *raw_buf = kmalloc(HDA_RING_BUFFER_SIZE + 128);
  if (!raw_buf)
    return -1;
  dma_buffer = (uint8_t *)(((uint64_t)raw_buf + 127) & ~127ULL);
  memset(dma_buffer, 0, HDA_RING_BUFFER_SIZE);
  memset(bdl, 0, HDA_RING_NUM_ENTRIES * sizeof(hda_bdl_entry_t));
  for (int i = 0; i < HDA_RING_NUM_ENTRIES; i++) {
    bdl[i].addr = (uint64_t)(dma_buffer + i * HDA_RING_ENTRY_SIZE);
    bdl[i].len = HDA_RING_ENTRY_SIZE;
    bdl[i].flags = (i == HDA_RING_NUM_ENTRIES - 1) ? 1 : 0; 
  }
  ring_write_pos = 0;
  ring_play_pos = 0;
  audio_playing = 0;
  return 0;
}

int blist_insertion_index(void* array, int array_length, array_element_comparer comparer) {
    int max = array_length;
    int min = 0;
    int mid = (max + min) >> 1;
    if (array_length == 0) {
        return 0;
    }
    for (int i = 0; i < array_length || i < 4; ++i) {
        int compare_result = comparer(array, mid, array_length);
        if (compare_result <= 0) {
            if (min == mid) {
                return mid + 1;
            }
            min = mid;
        } else {
            if (max == mid) {
                return mid;
            }
            max = mid;
        }
        mid = (max + min) >> 1;
    }
    assert(false);
    return mid;
}

