	uint8_t armed;
	FlightStatusArmedGet(&armed);
	if (save_needed) {
		if (armed == FLIGHTSTATUS_ARMED_DISARMED) {
			if (autotune_save_averaging()) {
				return;
			}
			float hover_throttle = ((float) (throttle_accumulator / update_counter)) / 10000.0f;
			UpdateSystemIdent(update_counter, hover_throttle,
					true);
			UAVObjSave(SystemIdentHandle(), 0);
			state = AT_INIT;
			save_needed = false;
		}
	}
	switch(state) {
		default:
		case AT_INIT:
			if (tune_running) {
				save_needed = false;
				state = AT_RUN;
			}
			break;
		case AT_RUN:
			(void) 0;
			float hover_throttle = ((float) (throttle_accumulator / update_counter)) / 10000.0f;
			UpdateSystemIdent(update_counter, hover_throttle,
					false);
			if (!tune_running) {
				if (update_counter > 12000) {
					save_needed = true;
				}
				state = AT_INIT;
			}
			break;
	}
}

static uint64_t apfs_fletcher64(const void *data, size_t len)
{
    const uint32_t *ptr = (const uint32_t *)data;
    uint64_t sum1 = 0, sum2 = 0;
    ptr += 2;
    len -= 8;
    while (len >= 4) {
        sum1 = (sum1 + *ptr++) % 0xFFFFFFFF;
        sum2 = (sum2 + sum1) % 0xFFFFFFFF;
        len -= 4;
    }
    return (sum2 << 32) | sum1;
}

