    if (h->rx_channel != NULL) {
        return ESP_OK;
    }
    lua_module_ir_assert_ctrl(h);
    rmt_rx_channel_config_t rx_cfg = {
        .clk_src = RMT_CLK_SRC_DEFAULT,
