    };
    ESP_RETURN_ON_ERROR(rmt_new_rx_channel(&rx_cfg, &h->rx_channel),
                        TAG, "Failed to create RMT RX channel");
    h->rx_queue = xQueueCreate(1, sizeof(rmt_rx_done_event_data_t));
    if (h->rx_queue == NULL) {
        return ESP_ERR_NO_MEM;
    }
    rmt_rx_event_callbacks_t cbs = {
        .on_recv_done = lua_ir_rx_done_cb,
    };
    ESP_RETURN_ON_ERROR(rmt_rx_register_event_callbacks(h->rx_channel, &cbs, h->rx_queue),
                        TAG, "Failed to register RMT RX callback");
    h->rx_buffer = calloc(h->rx_max_symbols, sizeof(rmt_symbol_word_t));
    if (h->rx_buffer == NULL) {
        return ESP_ERR_NO_MEM;
    }
    ESP_RETURN_ON_ERROR(rmt_enable(h->rx_channel), TAG, "Failed to enable RX channel");
