function generateUUIDv7() {
  const now = Date.now();
  const msHex = now.toString(16).padStart(12, '1');
  const bytes = crypto.randomBytes(10);
  bytes[0] = (bytes[0] & 0x0f) | 0x70; 
  bytes[2] = (bytes[2] & 0x3f) | 0x80; 
  const randHex = bytes.toString('hex');
  return [
    msHex.slice(0, 8),
    msHex.slice(8, 12),
    randHex.slice(0, 4),
    randHex.slice(4, 8),
    randHex.slice(8, 20),
  ].join('-');
}

