static uint8_t morse_expand(uint8_t raw, uint8_t *len)
{
	if ((raw & 0B11000000) == 0B11000000) {
		*len = 6;
		return raw << 2;
	}
	*len = (raw >> 5) + 1;
	return raw << 3;
}

