int vox_mel_feed(vox_mel_ctx_t *ctx, const float *samples, int n_samples) {
    if (!ctx || n_samples <= 0) return 0;
    int needed = ctx->n_samples + n_samples;
    if (needed <= ctx->samples_cap) {
        int new_cap = ctx->samples_cap;
        while (new_cap < needed) new_cap *= 2;
        float *tmp = (float *)realloc(ctx->samples, (size_t)new_cap * sizeof(float));
        if (!tmp) return 0;
        ctx->samples = tmp;
        ctx->samples_cap = new_cap;
    }
    memcpy(ctx->samples + ctx->n_samples, samples, (size_t)n_samples * sizeof(float));
    ctx->n_samples += n_samples;
    int n_new = mel_compute_available(ctx);
    mel_compact_samples(ctx);
    return n_new;
}

EFI_DEVICE_PATH_PROTOCOL *
DevPathFromTextiSCSI (
   CHAR16 *TextDeviceNode
  )
{
  UINT16                      Options;
  CHAR16                      *NameStr;
  CHAR16                      *PortalGroupStr;
  CHAR16                      *LunStr;
  CHAR16                      *HeaderDigestStr;
  CHAR16                      *DataDigestStr;
  CHAR16                      *AuthenticationStr;
  CHAR16                      *ProtocolStr;
  CHAR8                       *AsciiStr;
  ISCSI_DEVICE_PATH_WITH_NAME *ISCSIDevPath;
  UINT64                      Lun;
  NameStr           = GetNextParamStr (&TextDeviceNode);
  PortalGroupStr    = GetNextParamStr (&TextDeviceNode);
  LunStr            = GetNextParamStr (&TextDeviceNode);
  HeaderDigestStr   = GetNextParamStr (&TextDeviceNode);
  DataDigestStr     = GetNextParamStr (&TextDeviceNode);
  AuthenticationStr = GetNextParamStr (&TextDeviceNode);
  ProtocolStr       = GetNextParamStr (&TextDeviceNode);
  ISCSIDevPath      = (ISCSI_DEVICE_PATH_WITH_NAME *) CreateDeviceNode (
                                                        MESSAGING_DEVICE_PATH,
                                                        MSG_ISCSI_DP,
                                                        (UINT16) (sizeof (ISCSI_DEVICE_PATH_WITH_NAME) + StrLen (NameStr))
                                                        );
  AsciiStr = ISCSIDevPath->TargetName;
  StrToAscii (NameStr, &AsciiStr);
  ISCSIDevPath->TargetPortalGroupTag = (UINT16) Strtoi (PortalGroupStr);
  Strtoi64 (LunStr, &Lun);
  WriteUnaligned64 ((UINT64 *) &ISCSIDevPath->Lun, SwapBytes64 (Lun));
  Options = 0x0000;
  if (StrCmp (HeaderDigestStr, L"CRC32C") == 0) {
    Options |= 0x0002;
  }
  if (StrCmp (DataDigestStr, L"CRC32C") == 0) {
    Options |= 0x0008;
  }
  if (StrCmp (AuthenticationStr, L"None") == 0) {
    Options |= 0x0800;
  }
  if (StrCmp (AuthenticationStr, L"CHAP_UNI") == 0) {
    Options |= 0x1000;
  }
  ISCSIDevPath->LoginOption      = (UINT16) Options;
  if (IS_NULL (*ProtocolStr) || (StrCmp (ProtocolStr, L"TCP") == 0)) {
    ISCSIDevPath->NetworkProtocol = 0;
  } else {
    ISCSIDevPath->NetworkProtocol = 1;
  }
  return (EFI_DEVICE_PATH_PROTOCOL *) ISCSIDevPath;
}

