	switch (hostapd_get_oper_chwidth(iface->conf)) {
	case CONF_OPER_CHWIDTH_USE_HT:
		if (iface->conf->secondary_channel &&
		    iface->freq >= 2400 && iface->freq < 2500)
			center = iface->conf->channel +
				2 * iface->conf->secondary_channel;
