  function resetNativeMemBaseline() {
    _resetNativeMemBaseline = true;
  }
  return {
    reportCrash,
    reportHang,
    reportStuckLoop,
    startWatchdog,
    trackRoute,
    stop,
    resetNativeMemBaseline,
    _anonymize: anonymize,
    _stackSignature: stackSignature,
    _rateLimiter: rateLimiters,
